// ============================================================
// SHARED COLORS
// ============================================================
const Color _kBg    = Color(0xFF030310);
const Color _kNeonR = Color(0xFFFF2244);
const Color _kNeonC = Color(0xFF00FFFF);
const Color _kNeonM = Color(0xFFFF00CC);
const Color _kNeonO = Color(0xFFFF8800);
const Color _kNeonY = Color(0xFFFFEE00);
const Color _kNeonG = Color(0xFF00FF66);
const Color _kNeonB = Color(0xFF5555FF);
const Color _kGold  = Color(0xFFFFD700);

// ============================================================
// SHARED HELPER — GAME START PROMPT WIDGET
// ============================================================
Widget buildArenaStartPrompt({
  required BuildContext context,
  required String gameName,
  required String subtitle,
  required String story,
  required String controls,
  required Color accentColor,
  required Color secondColor,
  required int highScore,
  required VoidCallback onPlay,
  Widget? extraInfo,
}) {
  return Center(child: SingleChildScrollView(child: Container(
    margin: const EdgeInsets.all(20),
    padding: const EdgeInsets.all(24),
    decoration: BoxDecoration(
      color: Colors.black87,
      border: Border.all(color: accentColor, width: 2),
      borderRadius: BorderRadius.circular(24),
      boxShadow: [BoxShadow(color: accentColor.withValues(alpha: 0.4), blurRadius: 40, spreadRadius: 4)],
    ),
    child: Column(mainAxisSize: MainAxisSize.min, children: [
      Text(gameName, textAlign: TextAlign.center, style: TextStyle(
        color: accentColor, fontSize: 30, fontWeight: FontWeight.w900, letterSpacing: 4,
        shadows: [Shadow(color: accentColor, blurRadius: 20)],
      )),
      const SizedBox(height: 6),
      Text(subtitle, style: TextStyle(color: secondColor, fontSize: 13, letterSpacing: 3)),
      const SizedBox(height: 12),
      Container(padding: const EdgeInsets.all(10), decoration: BoxDecoration(
        color: Colors.white.withValues(alpha: 0.04), borderRadius: BorderRadius.circular(12)),
        child: Text(story, style: const TextStyle(color: Colors.white60, fontSize: 12, height: 1.6)),
      ),
      const SizedBox(height: 10),
      Container(padding: const EdgeInsets.all(10), decoration: BoxDecoration(
        color: accentColor.withValues(alpha: 0.06), borderRadius: BorderRadius.circular(12),
        border: Border.all(color: accentColor.withValues(alpha: 0.2))),
        child: Text('🎮 $controls', style: TextStyle(color: accentColor.withValues(alpha: 0.8), fontSize: 11, height: 1.5)),
      ),
      const SizedBox(height: 14),
      Text('🏆 HIGH SCORE: $highScore', style: TextStyle(color: _kGold, fontSize: 16, fontWeight: FontWeight.bold)),
      const SizedBox(height: 16),
      if (extraInfo != null) ...[extraInfo, const SizedBox(height: 14)],
      ElevatedButton.icon(
        style: ElevatedButton.styleFrom(
          backgroundColor: accentColor.withValues(alpha: 0.2),
          side: BorderSide(color: accentColor, width: 2),
          padding: const EdgeInsets.symmetric(horizontal: 36, vertical: 14),
        ),
        icon: Icon(Icons.play_arrow_rounded, color: accentColor, size: 26),
        label: Text('PLAY', style: TextStyle(color: accentColor, fontWeight: FontWeight.w900, fontSize: 20, letterSpacing: 2)),
        onPressed: onPlay,
      ),
      const SizedBox(height: 10),
      TextButton(
        onPressed: () => Navigator.pop(context),
        child: const Text('◀ BACK', style: TextStyle(color: Colors.white38)),
      ),
    ]),
  )));
}

// ============================================================
// SHARED GAME OVER WIDGET
// ============================================================
Widget buildArenaGameOver({
  required BuildContext context,
  required String gameName,
  required int score,
  required int highScore,
  required String extra,
  required Color accentColor,
  required VoidCallback onRetry,
  required VoidCallback onMenu,
}) {
  bool newRecord = score > highScore && score > 0;
  return Center(child: Container(
    margin: const EdgeInsets.all(24),
    padding: const EdgeInsets.all(28),
    decoration: BoxDecoration(
      color: Colors.black87,
      border: Border.all(color: accentColor, width: 2),
      borderRadius: BorderRadius.circular(24),
      boxShadow: [BoxShadow(color: accentColor.withValues(alpha: 0.5), blurRadius: 40)],
    ),
    child: Column(mainAxisSize: MainAxisSize.min, children: [
      Text('GAME OVER', style: TextStyle(color: accentColor, fontSize: 36, fontWeight: FontWeight.w900, letterSpacing: 4)),
      const SizedBox(height: 16),
      Text('SCORE: $score', style: const TextStyle(color: Colors.white, fontSize: 26, fontWeight: FontWeight.bold)),
      if (extra.isNotEmpty)
        Text(extra, style: const TextStyle(color: Colors.white70, fontSize: 15)),
      if (newRecord)
        Padding(padding: const EdgeInsets.only(top: 8), child: Text('🏆 NEW HIGH SCORE!',
          style: TextStyle(color: _kGold, fontSize: 18, fontWeight: FontWeight.w900,
            shadows: [Shadow(color: _kGold, blurRadius: 15)]))),
      const SizedBox(height: 24),
      Row(mainAxisSize: MainAxisSize.min, children: [
        ElevatedButton.icon(
          style: ElevatedButton.styleFrom(backgroundColor: accentColor, padding: const EdgeInsets.all(14)),
          icon: const Icon(Icons.replay, color: Colors.white),
          label: const Text('RETRY', style: TextStyle(color: Colors.white, fontWeight: FontWeight.bold)),
          onPressed: onRetry,
        ),
        const SizedBox(width: 12),
        OutlinedButton(
          style: OutlinedButton.styleFrom(side: const BorderSide(color: Colors.white30)),
          onPressed: onMenu,
          child: const Text('MENU', style: TextStyle(color: Colors.white54)),
        ),
      ]),
    ]),
  ));
}

// ============================================================
// NEON TANK WARS — DATA
// ============================================================
class NtWall { double x, y, w, h; NtWall(this.x, this.y, this.w, this.h); }
class NtProjectile { double x, y, vx, vy, life; Color color; bool friendly;
  NtProjectile({required this.x, required this.y, required this.vx, required this.vy,
    required this.color, required this.friendly}) : life = 1.0; }
class NtEnemy { double x, y, angle, speed, hp, maxHp, fireCooldown;
  int type; // 0=light 1=heavy 2=missile
  NtEnemy({required this.x, required this.y, required this.type, required this.hp,
    required this.speed, this.angle = 0, this.fireCooldown = 0}) : maxHp = hp; }
class NtPowerUp { double x, y; int type; // 0=health 1=speed 2=rapid
  NtPowerUp(this.x, this.y, this.type); }
class NtParticle { double x, y, vx, vy, life; Color color; double size;
  NtParticle({required this.x, required this.y, required this.vx, required this.vy,
    required this.life, required this.color, this.size = 3.0}); }

// ============================================================
// NEON TANK WARS GAME
// ============================================================
class NeonTankWarsGame extends StatefulWidget {
  const NeonTankWarsGame({Key? key}) : super(key: key);
  @override
  State<NeonTankWarsGame> createState() => _NeonTankWarsGameState();
}

class _NeonTankWarsGameState extends State<NeonTankWarsGame> with TickerProviderStateMixin {
  late AnimationController _loop;

  // State
  bool _playing = false, _over = false;
  int _score = 0, _highScore = 0, _lives = 3;
  double _health = 100;
  bool _rapidFire = false;
  double _rapidTimer = 0;
  double _speedBoost = 0;

  // Player
  double _px = 300, _py = 500;
  double _ptAngle = 0; // turret angle
  double _driveAngle = 0;
  Offset _moveDir = Offset.zero;
  Offset _aimDir = Offset.zero;

  // Fire
  double _fireCooldown = 0;
  bool _isFiring = false;

  // Entities
  final List<NtEnemy> _enemies = [];
  final List<NtProjectile> _projs = [];
  final List<NtParticle> _particles = [];
  final List<NtWall> _walls = [];
  final List<NtPowerUp> _powerUps = [];

  final Random _rnd = Random();
  int _wave = 1;
  double _damageFlash = 0;

  @override
  void initState() {
    super.initState();
    _loadHS();
    _loop = AnimationController(vsync: this, duration: const Duration(seconds: 1))..repeat();
    _loop.addListener(_update);
  }

  Future<void> _loadHS() async {
    final p = await SharedPreferences.getInstance();
    setState(() => _highScore = p.getInt('hi_score_neon_tank_wars') ?? 0);
  }

  Future<void> _saveHS() async {
    if (_score > _highScore) {
      final p = await SharedPreferences.getInstance();
      await p.setInt('hi_score_neon_tank_wars', _score);
      _highScore = _score;
    }
  }

  void _startGame() {
    setState(() {
      _playing = true; _over = false;
      _score = 0; _lives = 3; _health = 100; _wave = 1;
      _px = 180; _py = 400;
      _driveAngle = 0; _ptAngle = 0;
      _moveDir = Offset.zero; _aimDir = Offset.zero;
      _enemies.clear(); _projs.clear(); _particles.clear(); _powerUps.clear();
      _fireCooldown = 0; _rapidFire = false; _rapidTimer = 0; _speedBoost = 0;
      _damageFlash = 0;
      _buildWalls();
      _spawnEnemies();
    });
    HapticFeedback.mediumImpact();
  }

  void _buildWalls() {
    _walls.clear();
    // Border walls handled by arena bounds
    // Inner obstacles
    _walls.addAll([
      NtWall(100, 150, 80, 20), NtWall(250, 100, 20, 90),
      NtWall(50, 300, 20, 80), NtWall(130, 350, 100, 20),
      NtWall(300, 250, 20, 80), NtWall(200, 450, 70, 20),
      NtWall(350, 350, 20, 100),
    ]);
  }

  void _spawnEnemies() {
    int count = 3 + _wave * 2;
    for (int i = 0; i < count; i++) {
      double typeR = _rnd.nextDouble();
      int type = _wave > 2 && typeR > 0.65 ? 1 : _wave > 4 && typeR > 0.85 ? 2 : 0;
      _enemies.add(NtEnemy(
        x: 20.0 + _rnd.nextDouble() * 340,
        y: 20.0 + _rnd.nextDouble() * 200,
        type: type,
        hp: type == 0 ? 1 : type == 1 ? 3 : 2,
        speed: type == 0 ? 60 : type == 1 ? 30 : 70,
        fireCooldown: 1.5 + _rnd.nextDouble() * 2.0,
      ));
    }
  }

  void _update() {
    if (!_playing || _over) return;
    const double dt = 1 / 60;

    if (_damageFlash > 0) _damageFlash -= dt * 3;
    if (_fireCooldown > 0) _fireCooldown -= dt;
    if (_rapidFire) { _rapidTimer -= dt; if (_rapidTimer <= 0) _rapidFire = false; }
    if (_speedBoost > 0) _speedBoost -= dt;

    // Player movement
    if (_moveDir != Offset.zero) {
      double spd = (80 + (_speedBoost > 0 ? 40 : 0)) * dt;
      double newX = (_px + _moveDir.dx * spd).clamp(20, 360);
      double newY = (_py + _moveDir.dy * spd).clamp(20, 680);
      if (!_collidesWithWall(newX, newY, 14)) { _px = newX; _py = newY; }
      if (_moveDir.distance > 0.1) _driveAngle = atan2(_moveDir.dy, _moveDir.dx);
    }

    // Turret aiming
    if (_aimDir.distance > 0.1) _ptAngle = atan2(_aimDir.dy, _aimDir.dx);

    // Auto-fire when aiming
    if (_isFiring && _fireCooldown <= 0) _playerFire();

    // Enemy AI
    for (int i = _enemies.length - 1; i >= 0; i--) {
      var e = _enemies[i];
      double dx = _px - e.x, dy = _py - e.y;
      double dist = sqrt(dx * dx + dy * dy);
      if (dist > 0) { e.x += dx / dist * e.speed * dt; e.y += dy / dist * e.speed * dt; }
      e.angle = atan2(dy, dx);
      e.fireCooldown -= dt;
      if (e.fireCooldown <= 0) {
        if (dist < 250) {
          _projs.add(NtProjectile(x: e.x, y: e.y, vx: dx / dist * 180, vy: dy / dist * 180, color: _kNeonR, friendly: false));
          e.fireCooldown = e.type == 0 ? 1.8 : e.type == 1 ? 2.5 : 1.2;
        } else {
          e.fireCooldown = 0.5;
        }
      }
    }

    // Move projectiles
    for (int i = _projs.length - 1; i >= 0; i--) {
      var p = _projs[i];
      p.life -= dt * 2;
      p.x += p.vx * dt; p.y += p.vy * dt;

      bool hitWall = false;
      for (var w in _walls) {
        if (p.x > w.x && p.x < w.x + w.w && p.y > w.y && p.y < w.y + w.h) { hitWall = true; break; }
      }
      if (hitWall || p.life <= 0 || p.x < 0 || p.x > 380 || p.y < 0 || p.y > 700) {
        _projs.removeAt(i); continue;
      }

      if (p.friendly) {
        // Check enemy hits
        for (int j = _enemies.length - 1; j >= 0; j--) {
          var e = _enemies[j];
          double dx = e.x - p.x, dy = e.y - p.y;
          if (sqrt(dx * dx + dy * dy) < 18) {
            e.hp--;
            _spawnExpParts(e.x, e.y, e.type == 0 ? _kNeonC : e.type == 1 ? _kNeonO : _kNeonR);
            if (e.hp <= 0) {
              _score += e.type == 0 ? 100 : e.type == 1 ? 300 : 500;
              _enemies.removeAt(j);
              if (_rnd.nextDouble() < 0.2) _powerUps.add(NtPowerUp(e.x, e.y, _rnd.nextInt(3)));
            }
            _projs.removeAt(i);
            break;
          }
        }
      } else {
        // Check player hit
        double dx = _px - p.x, dy = _py - p.y;
        if (sqrt(dx * dx + dy * dy) < 16) {
          _projs.removeAt(i);
          _takeDmg(20);
          continue;
        }
      }
    }

    // Power-ups
    for (int i = _powerUps.length - 1; i >= 0; i--) {
      var pu = _powerUps[i];
      double dx = _px - pu.x, dy = _py - pu.y;
      if (sqrt(dx * dx + dy * dy) < 20) {
        switch (pu.type) {
          case 0: _health = (_health + 30).clamp(0, 100); break;
          case 1: _speedBoost = 5.0; break;
          case 2: _rapidFire = true; _rapidTimer = 5.0; break;
        }
        _powerUps.removeAt(i);
        HapticFeedback.lightImpact();
      }
    }

    // Particles
    for (int i = _particles.length - 1; i >= 0; i--) {
      var p = _particles[i];
      p.life -= dt; p.x += p.vx * dt; p.y += p.vy * dt;
      if (p.life <= 0) _particles.removeAt(i);
    }

    // Wave clear
    if (_enemies.isEmpty) {
      _wave++;
      _spawnEnemies();
      _health = (_health + 15).clamp(0, 100);
    }

    // Player-enemy collision
    for (var e in _enemies) {
      double dx = _px - e.x, dy = _py - e.y;
      if (sqrt(dx * dx + dy * dy) < 20) _takeDmg(30 * dt);
    }

    setState(() {});
  }

  bool _collidesWithWall(double x, double y, double r) {
    for (var w in _walls) {
      if (x + r > w.x && x - r < w.x + w.w && y + r > w.y && y - r < w.y + w.h) return true;
    }
    return false;
  }

  void _playerFire() {
    double cooldown = _rapidFire ? 0.08 : 0.2;
    if (_fireCooldown > 0) return;
    _fireCooldown = cooldown;
    double speed = 280;
    HapticFeedback.lightImpact();
    _projs.add(NtProjectile(x: _px, y: _py, vx: cos(_ptAngle) * speed, vy: sin(_ptAngle) * speed,
        color: _kNeonY, friendly: true));
    _spawnProjSpark(_px, _py);
  }

  void _spawnProjSpark(double x, double y) {
    for (int i = 0; i < 5; i++) {
      double ang = _ptAngle + (_rnd.nextDouble() - 0.5) * 0.5;
      _particles.add(NtParticle(x: x, y: y, vx: cos(ang) * 60, vy: sin(ang) * 60,
          life: 0.2, color: _kNeonY, size: 2));
    }
  }

  void _spawnExpParts(double x, double y, Color c) {
    for (int i = 0; i < 18; i++) {
      double ang = _rnd.nextDouble() * 2 * pi;
      double spd = 40 + _rnd.nextDouble() * 100;
      _particles.add(NtParticle(x: x, y: y, vx: cos(ang) * spd, vy: sin(ang) * spd,
          life: 0.5 + _rnd.nextDouble() * 0.5, color: c, size: 3 + _rnd.nextDouble() * 5));
    }
  }

  void _takeDmg(double amt) {
    _health -= amt;
    _damageFlash = 1.0;
    if (_health <= 0) {
      _lives--;
      if (_lives <= 0) { _over = true; _playing = false; _saveHS(); }
      else { _health = 100; HapticFeedback.heavyImpact(); }
    }
    setState(() {});
  }

  @override
  void dispose() { _loop.dispose(); super.dispose(); }

  @override
  Widget build(BuildContext context) {
    return Scaffold(backgroundColor: _kBg, body: Stack(children: [
      if (_playing || _over) Positioned.fill(child: CustomPaint(painter: NtPainter(
        px: _px, py: _py, driveAngle: _driveAngle, ptAngle: _ptAngle,
        enemies: List.from(_enemies), projs: List.from(_projs),
        particles: List.from(_particles), walls: List.from(_walls),
        powerUps: List.from(_powerUps), damageFlash: _damageFlash,
        rapidFire: _rapidFire, speedBoost: _speedBoost > 0,
      ))),

      // HUD
      if (_playing && !_over) ...[
        Positioned(top: 44, left: 16, child: Column(crossAxisAlignment: CrossAxisAlignment.start, children: [
          Text('WAVE $_wave', style: TextStyle(color: _kNeonY, fontSize: 22, fontWeight: FontWeight.w900,
            shadows: [Shadow(color: _kNeonY, blurRadius: 10)])),
          Text('SCORE: $_score', style: const TextStyle(color: Colors.white, fontSize: 16, fontWeight: FontWeight.bold)),
          Row(children: List.generate(_lives, (_) => const Icon(Icons.star_rounded, color: _kNeonY, size: 16))),
          if (_rapidFire) Text('⚡ RAPID FIRE!', style: TextStyle(color: _kNeonY, fontSize: 13, fontWeight: FontWeight.bold,
            shadows: [Shadow(color: _kNeonY, blurRadius: 8)])),
          if (_speedBoost > 0) Text('💨 SPEED BOOST!', style: TextStyle(color: _kNeonG, fontSize: 13, fontWeight: FontWeight.bold)),
        ])),
        Positioned(top: 44, right: 16, child: Row(children: [
          Icon(Icons.shield_outlined, color: _kNeonC, size: 16),
          const SizedBox(width: 6),
          Container(width: 90, height: 10, decoration: BoxDecoration(color: Colors.white12, borderRadius: BorderRadius.circular(5)),
            child: FractionallySizedBox(widthFactor: (_health / 100).clamp(0, 1), alignment: Alignment.centerLeft,
              child: Container(decoration: BoxDecoration(color: _kNeonC, borderRadius: BorderRadius.circular(5),
                boxShadow: [const BoxShadow(color: _kNeonC, blurRadius: 6)])))),
        ])),
        // Controls
        Positioned(bottom: 16, left: 16, right: 16, child: SizedBox(height: 190, child: Row(
          mainAxisAlignment: MainAxisAlignment.spaceBetween, children: [
          VirtualJoystick(size: 120, baseColor: Colors.white12, knobColor: _kNeonC,
            onDirectionChanged: (dir) => setState(() => _moveDir = dir)),
          Row(children: [
            ActionButton(icon: Icons.gps_fixed, color: _kNeonR, label: 'FIRE',
              onPressStart: () => setState(() => _isFiring = true),
              onPressEnd: () => setState(() => _isFiring = false),
              onPressed: _playerFire, size: 72),
            const SizedBox(width: 12),
            VirtualJoystick(size: 110, baseColor: Colors.white12, knobColor: _kNeonO,
              onDirectionChanged: (dir) => setState(() => _aimDir = dir)),
          ]),
        ]))),
      ],

      // Start / Game Over
      if (!_playing && !_over) buildArenaStartPrompt(
        context: context, gameName: 'NEON TANK WARS', subtitle: 'TWIN-STICK ARENA BATTLE',
        story: 'Commander HAVOC controls the last functioning battle tank in Neo-Citadel. '
            'Cyber-Faction armored divisions have surrounded the city. '
            'Destroy every enemy tank before they breach the core!',
        controls: 'Left stick: Drive tank • Right stick: Aim turret • Fire button: Shoot shells\nCollect power-ups (💊 health, ⚡ rapid fire, 💨 speed)',
        accentColor: _kNeonY, secondColor: _kNeonO,
        highScore: _highScore, onPlay: _startGame,
      ),
      if (_over) buildArenaGameOver(
        context: context, gameName: 'NEON TANK WARS', score: _score, highScore: _highScore,
        extra: 'WAVE: $_wave', accentColor: _kNeonY,
        onRetry: _startGame,
        onMenu: () => setState(() { _over = false; _playing = false; }),
      ),
    ]));
  }
}

// ============================================================
// NEON TANK WARS PAINTER
// ============================================================
class NtPainter extends CustomPainter {
  final double px, py, driveAngle, ptAngle, damageFlash;
  final bool rapidFire, speedBoost;
  final List<NtEnemy> enemies;
  final List<NtProjectile> projs;
  final List<NtParticle> particles;
  final List<NtWall> walls;
  final List<NtPowerUp> powerUps;

  NtPainter({required this.px, required this.py, required this.driveAngle, required this.ptAngle,
    required this.enemies, required this.projs, required this.particles, required this.walls,
    required this.powerUps, required this.damageFlash, required this.rapidFire, required this.speedBoost});

  @override
  void paint(Canvas canvas, Size size) {
    double scaleX = size.width / 380; double scaleY = size.height / 700;
    canvas.save();
    canvas.scale(scaleX, scaleY);

    // Background grid
    canvas.drawRect(const Rect.fromLTWH(0, 0, 380, 700), Paint()..color = const Color(0xFF020218));
    for (int i = 0; i <= 38; i++) {
      canvas.drawLine(Offset(i * 10, 0), Offset(i * 10, 700), Paint()..color = _kNeonB.withValues(alpha: 0.12)..strokeWidth = 0.5);
    }
    for (int i = 0; i <= 70; i++) {
      canvas.drawLine(Offset(0, i * 10), Offset(380, i * 10), Paint()..color = _kNeonB.withValues(alpha: 0.12)..strokeWidth = 0.5);
    }

    // Walls
    for (var w in walls) {
      canvas.drawRect(Rect.fromLTWH(w.x, w.y, w.w, w.h),
          Paint()..color = const Color(0xFF334455));
      canvas.drawRect(Rect.fromLTWH(w.x, w.y, w.w, w.h),
          Paint()..color = _kNeonC.withValues(alpha: 0.4)..style = PaintingStyle.stroke..strokeWidth = 1.5
            ..maskFilter = const MaskFilter.blur(BlurStyle.normal, 3));
    }

    // Power-ups
    for (var pu in powerUps) {
      Color c = pu.type == 0 ? Colors.green : pu.type == 1 ? _kNeonC : _kNeonY;
      canvas.drawCircle(Offset(pu.x, pu.y), 10, Paint()..color = c.withValues(alpha: 0.3)
        ..maskFilter = const MaskFilter.blur(BlurStyle.normal, 8));
      canvas.drawCircle(Offset(pu.x, pu.y), 10, Paint()..color = c..style = PaintingStyle.stroke..strokeWidth = 2);
    }

    // Projectiles
    for (var p in projs) {
      canvas.drawCircle(Offset(p.x, p.y), 5,
          Paint()..color = p.color..maskFilter = const MaskFilter.blur(BlurStyle.normal, 4));
      canvas.drawCircle(Offset(p.x, p.y), 3, Paint()..color = Colors.white);
    }

    // Enemies
    for (var e in enemies) {
      Color c = e.type == 0 ? _kNeonC : e.type == 1 ? _kNeonO : _kNeonR;
      double r = e.type == 1 ? 16 : 12;
      canvas.save();
      canvas.translate(e.x, e.y);
      canvas.rotate(e.angle + pi / 2);
      // Body
      canvas.drawRRect(RRect.fromRectAndRadius(Rect.fromCenter(center: Offset.zero, width: r * 1.6, height: r * 2.2), Radius.circular(r * 0.3)),
          Paint()..color = c.withValues(alpha: 0.7));
      canvas.drawRRect(RRect.fromRectAndRadius(Rect.fromCenter(center: Offset.zero, width: r * 1.6, height: r * 2.2), Radius.circular(r * 0.3)),
          Paint()..color = c..style = PaintingStyle.stroke..strokeWidth = 1.5
            ..maskFilter = const MaskFilter.blur(BlurStyle.normal, 4));
      // Turret
      canvas.drawLine(Offset.zero, Offset(0, -r * 1.6), Paint()..color = c..strokeWidth = 4..strokeCap = StrokeCap.round);
      canvas.restore();
      // HP bar
      if (e.maxHp > 1) {
        double bw = r * 2.4;
        canvas.drawRect(Rect.fromLTWH(e.x - bw / 2, e.y - r * 1.5 - 8, bw, 4), Paint()..color = Colors.black45);
        canvas.drawRect(Rect.fromLTWH(e.x - bw / 2, e.y - r * 1.5 - 8, bw * e.hp / e.maxHp, 4), Paint()..color = c);
      }
    }

    // Player tank
    canvas.save();
    canvas.translate(px, py);
    canvas.rotate(driveAngle + pi / 2);
    Color pBodyColor = speedBoost ? _kNeonG : _kNeonY;
    canvas.drawRRect(RRect.fromRectAndRadius(Rect.fromCenter(center: Offset.zero, width: 22, height: 34), const Radius.circular(4)),
        Paint()..color = pBodyColor.withValues(alpha: 0.8));
    canvas.drawRRect(RRect.fromRectAndRadius(Rect.fromCenter(center: Offset.zero, width: 22, height: 34), const Radius.circular(4)),
        Paint()..color = pBodyColor..style = PaintingStyle.stroke..strokeWidth = 2
          ..maskFilter = const MaskFilter.blur(BlurStyle.normal, 6));
    canvas.restore();
    // Turret (separate rotation)
    canvas.save();
    canvas.translate(px, py);
    canvas.rotate(ptAngle + pi / 2);
    Color turretColor = rapidFire ? _kNeonR : Colors.white;
    canvas.drawLine(Offset.zero, const Offset(0, -22), Paint()..color = turretColor..strokeWidth = 5..strokeCap = StrokeCap.round);
    canvas.restore();

    // Particles
    for (var p in particles) {
      canvas.drawCircle(Offset(p.x, p.y), p.size,
          Paint()..color = p.color.withValues(alpha: p.life.clamp(0, 1))
            ..maskFilter = MaskFilter.blur(BlurStyle.normal, p.size * 0.4));
    }

    canvas.restore();

    // Damage flash overlay
    if (damageFlash > 0) {
      canvas.drawRect(Rect.fromLTWH(0, 0, size.width, size.height),
          Paint()..color = _kNeonR.withValues(alpha: damageFlash * 0.4));
    }
  }

  @override
  bool shouldRepaint(covariant CustomPainter old) => true;
}

// ============================================================
// BLADE RUNNER X — DATA
// ============================================================
class BrxObstacle {
  double x, y, w, h, speed;
  int type; // 0=laser(jump) 1=drone(slide) 2=wall(slash)
  bool destroyed;
  BrxObstacle({required this.x, required this.y, required this.w, required this.h,
    required this.type, required this.speed}) : destroyed = false;
}

class BrxChip { double x, y; bool collected; BrxChip(this.x, this.y) : collected = false; }

class BrxParticle { double x, y, vx, vy, life; Color color; double size;
  BrxParticle({required this.x, required this.y, required this.vx, required this.vy,
    required this.life, required this.color, this.size = 3.0}); }

class BrxBuildingLayer { double x, y, w, h, scrollSpeed; Color color;
  BrxBuildingLayer({required this.x, required this.y, required this.w, required this.h,
    required this.scrollSpeed, required this.color}); }

// ============================================================
// BLADE RUNNER X GAME
// ============================================================
class BladeRunnerXGame extends StatefulWidget {
  const BladeRunnerXGame({Key? key}) : super(key: key);
  @override
  State<BladeRunnerXGame> createState() => _BladeRunnerXGameState();
}

class _BladeRunnerXGameState extends State<BladeRunnerXGame> with TickerProviderStateMixin {
  late AnimationController _loop;

  bool _playing = false, _over = false;
  int _score = 0, _highScore = 0, _combo = 0;
  double _distance = 0.0;
  double _speed = 200.0; // pixels per second
  bool _isSliding = false;
  bool _isSlashing = false;
  double _slashCooldown = 0;
  double _slashTimer = 0;
  double _comboTimer = 0;
  double _damageFlash = 0;

  // Player
  double _py = 0; // y offset (jumping)
  double _vy = 0;
  bool _canDoubleJump = true;
  bool _isGrounded = true;

  // Entities
  final List<BrxObstacle> _obstacles = [];
  final List<BrxChip> _chips = [];
  final List<BrxParticle> _particles = [];
  final List<BrxBuildingLayer> _buildings = [];

  final Random _rnd = Random();
  double _spawnTimer = 0;
  double _chipTimer = 0;

  static const double groundY = 0.72; // fractional screen position
  static const double playerX = 0.18; // fractional
  int _health = 3;

  @override
  void initState() {
    super.initState();
    _loadHS();
    _loop = AnimationController(vsync: this, duration: const Duration(seconds: 1))..repeat();
    _loop.addListener(_update);
    _buildBuildings();
  }

  void _buildBuildings() {
    _buildings.clear();
    final rnd = Random(99);
    for (int i = 0; i < 30; i++) {
      _buildings.add(BrxBuildingLayer(
        x: rnd.nextDouble() * 800,
        y: (0.05 + rnd.nextDouble() * 0.5),
        w: 30 + rnd.nextDouble() * 60,
        h: 0.2 + rnd.nextDouble() * 0.5,
        scrollSpeed: 60 + rnd.nextDouble() * 100,
        color: Color.fromRGBO(10 + rnd.nextInt(30), 5 + rnd.nextInt(20), 30 + rnd.nextInt(60), 1),
      ));
    }
  }

  Future<void> _loadHS() async {
    final p = await SharedPreferences.getInstance();
    setState(() => _highScore = p.getInt('hi_score_blade_runner_x') ?? 0);
  }

  Future<void> _saveHS() async {
    if (_score > _highScore) {
      final p = await SharedPreferences.getInstance();
      await p.setInt('hi_score_blade_runner_x', _score);
      _highScore = _score;
    }
  }

  void _startGame() {
    setState(() {
      _playing = true; _over = false;
      _score = 0; _combo = 0; _distance = 0; _speed = 200;
      _py = 0; _vy = 0; _isGrounded = true; _canDoubleJump = true;
      _isSliding = false; _isSlashing = false;
      _slashCooldown = 0; _slashTimer = 0; _comboTimer = 0; _damageFlash = 0;
      _health = 3;
      _obstacles.clear(); _chips.clear(); _particles.clear();
      _spawnTimer = 0; _chipTimer = 0;
    });
    HapticFeedback.mediumImpact();
  }

  void _jump() {
    if (_isGrounded) {
      _vy = -620; _isGrounded = false; _canDoubleJump = true; _isSliding = false;
      HapticFeedback.lightImpact();
      _spawnJumpParticles();
    } else if (_canDoubleJump) {
      _vy = -500; _canDoubleJump = false;
      HapticFeedback.lightImpact();
      _spawnJumpParticles();
    }
  }

  void _slide() {
    if (_isGrounded && !_isSliding) {
      _isSliding = true;
      HapticFeedback.lightImpact();
    }
  }

  void _slash() {
    if (_slashCooldown > 0) return;
    _isSlashing = true; _slashTimer = 0.2; _slashCooldown = 0.8;
    HapticFeedback.mediumImpact();
    _spawnSlashParticles();
    // Destroy slashable obstacles
    for (var o in _obstacles) {
      if (!o.destroyed && o.type == 2 && o.x < 0.35 && o.x > 0.08) {
        o.destroyed = true;
        _combo++;
        _comboTimer = 2.0;
        _score += 50 * (_combo + 1);
        _spawnDestroyParticles(o.x, o.y, _kNeonM);
      }
    }
  }

  void _spawnJumpParticles() {
    for (int i = 0; i < 8; i++) {
      double ang = pi + (_rnd.nextDouble() - 0.5) * pi * 0.7;
      _particles.add(BrxParticle(x: playerX, y: groundY, vx: cos(ang) * 0.08, vy: sin(ang) * 0.08,
          life: 0.4, color: _kNeonM, size: 3));
    }
  }

  void _spawnSlashParticles() {
    for (int i = 0; i < 16; i++) {
      double ang = (_rnd.nextDouble() - 0.5) * pi * 0.6;
      _particles.add(BrxParticle(x: playerX + 0.05, y: groundY - 0.15,
          vx: cos(ang) * 0.15, vy: sin(ang) * 0.06, life: 0.3, color: _kNeonC, size: 2));
    }
  }

  void _spawnDestroyParticles(double x, double y, Color c) {
    for (int i = 0; i < 20; i++) {
      double ang = _rnd.nextDouble() * 2 * pi;
      _particles.add(BrxParticle(x: x, y: y, vx: cos(ang) * 0.12, vy: sin(ang) * 0.12,
          life: 0.5, color: c, size: 4));
    }
  }

  void _update() {
    if (!_playing || _over) return;
    const double dt = 1 / 60;

    _distance += _speed * dt;
    _score = (_distance / 10).toInt() + _chips.where((c) => c.collected).length * 10;
    _speed = (200 + _distance / 200).clamp(200, 450);

    if (_damageFlash > 0) _damageFlash -= dt * 3;
    if (_slashCooldown > 0) _slashCooldown -= dt;
    if (_comboTimer > 0) { _comboTimer -= dt; if (_comboTimer <= 0) _combo = 0; }
    if (_slashTimer > 0) { _slashTimer -= dt; if (_slashTimer <= 0) _isSlashing = false; }

    // Physics
    if (!_isGrounded) {
      _py += _vy * dt;
      _vy += 1400 * dt; // gravity
      if (_py >= 0) { _py = 0; _vy = 0; _isGrounded = true; _canDoubleJump = true; _isSliding = false; }
    }

    // Scroll buildings
    for (var b in _buildings) {
      b.x -= b.scrollSpeed * dt / 800;
      if (b.x < -b.w / 800) b.x = 1.0 + b.w / 800;
    }

    // Spawn obstacles
    _spawnTimer += dt;
    if (_spawnTimer > (1.5 - _speed / 600).clamp(0.5, 1.5)) {
      _spawnTimer = 0;
      int type = _rnd.nextInt(3);
      _obstacles.add(BrxObstacle(
        x: 1.05, y: type == 0 ? groundY - 0.05 : type == 1 ? groundY - 0.22 : groundY - 0.28,
        w: type == 2 ? 0.03 : 0.04, h: type == 0 ? 0.12 : type == 1 ? 0.06 : 0.30,
        type: type, speed: _speed,
      ));
    }

    // Spawn chips
    _chipTimer += dt;
    if (_chipTimer > 0.8) {
      _chipTimer = 0;
      if (_rnd.nextDouble() > 0.4) _chips.add(BrxChip(1.02, groundY - 0.1 - _rnd.nextDouble() * 0.2));
    }

    // Move obstacles
    double playerH = _isSliding ? 0.06 : 0.25;
    double playerTop = groundY + _py / 800 - playerH;
    double playerBottom = groundY + _py / 800;

    for (int i = _obstacles.length - 1; i >= 0; i--) {
      var o = _obstacles[i];
      if (o.destroyed) { _obstacles.removeAt(i); continue; }
      o.x -= o.speed * dt / 800;
      if (o.x < -0.1) { _obstacles.removeAt(i); continue; }

      // Collision with player
      bool xOverlap = playerX + 0.06 > o.x && playerX - 0.02 < o.x + o.w;
      bool yOverlap = playerBottom > o.y && playerTop < o.y + o.h;
      if (xOverlap && yOverlap && !o.destroyed) {
        if (o.type == 2 && _isSlashing) {
          o.destroyed = true;
          _combo++;
          _comboTimer = 2.0;
          _spawnDestroyParticles(o.x, o.y, _kNeonM);
        } else {
          o.destroyed = true;
          _health--;
          _damageFlash = 1.0;
          HapticFeedback.heavyImpact();
          if (_health <= 0) { _over = true; _playing = false; _saveHS(); }
        }
      }
    }

    // Chips collection
    for (int i = _chips.length - 1; i >= 0; i--) {
      var c = _chips[i];
      c.x -= _speed * dt / 800;
      if (c.collected || c.x < -0.05) { _chips.removeAt(i); continue; }
      if ((c.x - playerX).abs() < 0.06 && (c.y - (groundY - 0.1)).abs() < 0.12) {
        c.collected = true; _score += 10 * (1 + _combo);
        _combo++; _comboTimer = 2.0;
        HapticFeedback.lightImpact();
      }
    }

    // Particles
    for (int i = _particles.length - 1; i >= 0; i--) {
      var p = _particles[i];
      p.life -= dt; p.x += p.vx; p.y += p.vy;
      if (p.life <= 0 || p.x < 0 || p.x > 1) _particles.removeAt(i);
    }

    setState(() {});
  }

  @override
  void dispose() { _loop.dispose(); super.dispose(); }

  @override
  Widget build(BuildContext context) {
    return Scaffold(backgroundColor: _kBg, body: GestureDetector(
      onTapDown: (_) => _jump(),
      onVerticalDragDown: (d) => d.globalPosition.dy > MediaQuery.of(context).size.height * 0.6 ? _slide() : _jump(),
      child: Stack(children: [
        if (_playing || _over) Positioned.fill(child: CustomPaint(painter: BrxPainter(
          py: _py, isSliding: _isSliding, isSlashing: _isSlashing,
          obstacles: List.from(_obstacles), chips: List.from(_chips),
          particles: List.from(_particles), buildings: List.from(_buildings),
          damageFlash: _damageFlash, health: _health,
        ))),

        // HUD
        if (_playing && !_over) ...[
          Positioned(top: 44, left: 16, child: Column(crossAxisAlignment: CrossAxisAlignment.start, children: [
            Text('SCORE: $_score', style: TextStyle(color: _kNeonM, fontSize: 20, fontWeight: FontWeight.w900,
              shadows: [Shadow(color: _kNeonM, blurRadius: 10)])),
            Text('DISTANCE: ${(_distance / 10).toInt()}m', style: const TextStyle(color: Colors.white70, fontSize: 14)),
            if (_combo > 1) Text('COMBO x$_combo!', style: TextStyle(color: _kNeonY, fontSize: 16,
              fontWeight: FontWeight.bold, shadows: [Shadow(color: _kNeonY, blurRadius: 8)])),
          ])),
          Positioned(top: 44, right: 16, child: Row(children: List.generate(_health,
              (_) => const Icon(Icons.favorite_rounded, color: _kNeonM, size: 20)))),
          // Slash button
          Positioned(bottom: 60, right: 24, child: Column(mainAxisSize: MainAxisSize.min, children: [
            ActionButton(icon: Icons.flash_on_rounded, color: _kNeonC, label: 'SLASH',
              onPressed: _slash, size: 66),
            const SizedBox(height: 8),
            ActionButton(icon: Icons.arrow_upward_rounded, color: _kNeonM, label: 'JUMP',
              onPressed: _jump, size: 60),
            const SizedBox(height: 8),
            ActionButton(icon: Icons.arrow_downward_rounded, color: _kNeonO, label: 'SLIDE',
              onPressed: _slide, size: 52),
          ])),
        ],

        if (!_playing && !_over) buildArenaStartPrompt(
          context: context, gameName: 'BLADE RUNNER X', subtitle: 'CYBERPUNK ENDLESS RUNNER',
          story: 'Agent VEYRA has gone rogue, sprinting through Neo-Tokyo\'s megastructure. '
              'Dodge laser barriers, slide under surveillance drones, and slash through security walls. '
              'The Megacorp bounty hunters are closing in — run or die!',
          controls: 'TAP anywhere: Jump • Double-tap: Double jump • Swipe down: Slide\nSLASH button: Destroy walls • Collect 💾 data chips for bonus score',
          accentColor: _kNeonM, secondColor: _kNeonC,
          highScore: _highScore, onPlay: _startGame,
        ),
        if (_over) buildArenaGameOver(
          context: context, gameName: 'BLADE RUNNER X', score: _score, highScore: _highScore,
          extra: 'DISTANCE: ${(_distance / 10).toInt()}m', accentColor: _kNeonM,
          onRetry: _startGame,
          onMenu: () => setState(() { _over = false; _playing = false; }),
        ),
      ]),
    ));
  }
}

// ============================================================
// BLADE RUNNER X PAINTER
// ============================================================
class BrxPainter extends CustomPainter {
  final double py, damageFlash;
  final bool isSliding, isSlashing;
  final int health;
  final List<BrxObstacle> obstacles;
  final List<BrxChip> chips;
  final List<BrxParticle> particles;
  final List<BrxBuildingLayer> buildings;

  BrxPainter({required this.py, required this.isSliding, required this.isSlashing,
    required this.obstacles, required this.chips, required this.particles, required this.buildings,
    required this.damageFlash, required this.health});

  @override
  void paint(Canvas canvas, Size size) {
    // Dark cyberpunk bg
    canvas.drawRect(Rect.fromLTWH(0, 0, size.width, size.height),
        Paint()..shader = LinearGradient(begin: Alignment.topCenter, end: Alignment.bottomCenter,
          colors: [const Color(0xFF03010F), const Color(0xFF060220)]).createShader(
          Rect.fromLTWH(0, 0, size.width, size.height)));

    // Stars
    final rnd = Random(42);
    for (int i = 0; i < 80; i++) {
      canvas.drawCircle(Offset(rnd.nextDouble() * size.width, rnd.nextDouble() * size.height * 0.6),
          rnd.nextDouble() * 1.5, Paint()..color = Colors.white.withValues(alpha: 0.3 + rnd.nextDouble() * 0.5));
    }

    // Buildings (parallax)
    for (var b in buildings) {
      canvas.drawRect(Rect.fromLTRB(b.x * size.width, (b.y) * size.height,
          (b.x + b.w / size.width) * size.width, (b.y + b.h) * size.height), Paint()..color = b.color);
      // Window lights
      int winRows = ((b.h * size.height) / 12).toInt();
      int winCols = 3;
      for (int r = 0; r < winRows; r++) {
        for (int c = 0; c < winCols; c++) {
          if (rnd.nextDouble() > 0.35) {
            canvas.drawRect(Rect.fromLTWH(
              b.x * size.width + 4 + c * 8, b.y * size.height + 4 + r * 12, 5, 7),
              Paint()..color = Color.fromRGBO(200, 200, 50 + rnd.nextInt(150), rnd.nextDouble() * 0.6 + 0.1));
          }
        }
      }
    }

    // Ground
    final ground = size.height * 0.72;
    canvas.drawRect(Rect.fromLTRB(0, ground, size.width, size.height),
        Paint()..color = const Color(0xFF0D0820));
    canvas.drawLine(Offset(0, ground), Offset(size.width, ground),
        Paint()..color = _kNeonM.withValues(alpha: 0.6)..strokeWidth = 2
          ..maskFilter = const MaskFilter.blur(BlurStyle.normal, 4));

    // Ground grid
    for (int i = 0; i < 10; i++) {
      double y = ground + i * (size.height - ground) / 8;
      canvas.drawLine(Offset(0, y), Offset(size.width, y),
          Paint()..color = _kNeonM.withValues(alpha: 0.07 + i * 0.01)..strokeWidth = 0.5);
    }

    // Chips
    for (var c in chips) {
      if (!c.collected) {
        canvas.drawRRect(RRect.fromRectAndRadius(
          Rect.fromCenter(center: Offset(c.x * size.width, c.y * size.height), width: 16, height: 10),
          const Radius.circular(3)),
          Paint()..color = _kNeonG.withValues(alpha: 0.8)..maskFilter = const MaskFilter.blur(BlurStyle.normal, 3));
        canvas.drawRRect(RRect.fromRectAndRadius(
          Rect.fromCenter(center: Offset(c.x * size.width, c.y * size.height), width: 16, height: 10),
          const Radius.circular(3)),
          Paint()..color = _kNeonG..style = PaintingStyle.stroke..strokeWidth = 1.5);
      }
    }

    // Obstacles
    for (var o in obstacles) {
      if (o.destroyed) continue;
      Color c = o.type == 0 ? _kNeonR : o.type == 1 ? _kNeonC : _kNeonM;
      double ox = o.x * size.width, oy = o.y * size.height, ow = o.w * size.width, oh = o.h * size.height;
      if (o.type == 0) {
        // Laser — horizontal red beam
        canvas.drawRect(Rect.fromLTWH(ox, oy, ow, oh), Paint()..color = c.withValues(alpha: 0.2));
        canvas.drawRect(Rect.fromLTWH(ox, oy, ow, 2), Paint()..color = c
          ..maskFilter = const MaskFilter.blur(BlurStyle.normal, 6));
      } else if (o.type == 1) {
        // Drone
        canvas.drawOval(Rect.fromLTWH(ox, oy, ow * 2.5, oh),
            Paint()..color = c.withValues(alpha: 0.7)..maskFilter = const MaskFilter.blur(BlurStyle.normal, 4));
      } else {
        // Wall
        canvas.drawRect(Rect.fromLTWH(ox, oy, ow, oh),
            Paint()..color = c.withValues(alpha: 0.5));
        canvas.drawRect(Rect.fromLTWH(ox, oy, ow, oh),
            Paint()..color = c..style = PaintingStyle.stroke..strokeWidth = 2
              ..maskFilter = const MaskFilter.blur(BlurStyle.normal, 5));
      }
    }

    // Player
    double playerX = 0.18 * size.width;
    double playerY = ground + py;
    double pw = 22, ph = isSliding ? 14 : 38;
    // Body glow
    canvas.drawRRect(RRect.fromRectAndRadius(
      Rect.fromLTWH(playerX - pw / 2, playerY - ph, pw, ph), const Radius.circular(4)),
      Paint()..color = _kNeonM.withValues(alpha: 0.35)..maskFilter = const MaskFilter.blur(BlurStyle.normal, 8));
    // Body
    canvas.drawRRect(RRect.fromRectAndRadius(
      Rect.fromLTWH(playerX - pw / 2, playerY - ph, pw, ph), const Radius.circular(4)),
      Paint()..color = _kNeonM.withValues(alpha: 0.8));
    // Visor / head
    if (!isSliding) {
      canvas.drawOval(Rect.fromCenter(center: Offset(playerX, playerY - ph - 8), width: 16, height: 14),
          Paint()..color = _kNeonC.withValues(alpha: 0.9)
            ..maskFilter = const MaskFilter.blur(BlurStyle.normal, 4));
    }
    // Slash effect
    if (isSlashing) {
      canvas.drawLine(Offset(playerX, playerY - ph * 0.6), Offset(playerX + 70, playerY - ph * 0.8),
          Paint()..color = _kNeonC..strokeWidth = 3..strokeCap = StrokeCap.round
            ..maskFilter = const MaskFilter.blur(BlurStyle.normal, 6));
      canvas.drawLine(Offset(playerX + 10, playerY - ph * 0.3), Offset(playerX + 70, playerY - ph * 0.1),
          Paint()..color = _kNeonC..strokeWidth = 2..strokeCap = StrokeCap.round
            ..maskFilter = const MaskFilter.blur(BlurStyle.normal, 4));
    }

    // Particles
    for (var p in particles) {
      canvas.drawCircle(Offset(p.x * size.width, p.y * size.height), p.size,
          Paint()..color = p.color.withValues(alpha: p.life.clamp(0, 1))
            ..maskFilter = MaskFilter.blur(BlurStyle.normal, p.size * 0.3));
    }

    // Damage flash
    if (damageFlash > 0) {
      canvas.drawRect(Rect.fromLTWH(0, 0, size.width, size.height),
          Paint()..color = _kNeonR.withValues(alpha: damageFlash * 0.4));
    }
  }

  @override
  bool shouldRepaint(covariant CustomPainter old) => true;
}

// ============================================================
// ASTRO DOGFIGHT — DATA
// ============================================================
class AdShip {
  double x, y, vx, vy, angle, hp, maxHp, fireCooldown;
  int type; // 0=fighter 1=bomber 2=ace
  bool isDying; double dieTimer;
  AdShip({required this.x, required this.y, required this.type, required this.hp,
    this.vx = 0, this.vy = 0, this.angle = 0, this.fireCooldown = 0}) : maxHp = hp, isDying = false, dieTimer = 0;
}

class AdProjectile { double x, y, vx, vy, life; bool friendly; bool homing; AdShip? target;
  AdProjectile({required this.x, required this.y, required this.vx, required this.vy,
    required this.friendly, this.homing = false, this.target}): life = 1.0; }
class AdMine { double x, y; AdMine(this.x, this.y); }
class AdStar { double x, y, r, speed; AdStar({required this.x, required this.y, required this.r, required this.speed}); }
class AdPowerUp { double x, y; int type; AdPowerUp(this.x, this.y, this.type); }
class AdParticle { double x, y, vx, vy, life; Color color; double size;
  AdParticle({required this.x, required this.y, required this.vx, required this.vy,
    required this.life, required this.color, this.size = 3.0}); }

// ============================================================
// ASTRO DOGFIGHT GAME
// ============================================================
class AstroDogfightGame extends StatefulWidget {
  const AstroDogfightGame({Key? key}) : super(key: key);
  @override
  State<AstroDogfightGame> createState() => _AstroDogfightGameState();
}

class _AstroDogfightGameState extends State<AstroDogfightGame> with TickerProviderStateMixin {
  late AnimationController _loop;

  bool _playing = false, _over = false;
  int _score = 0, _highScore = 0;
  double _health = 100;
  bool _shielded = false;
  double _shieldTimer = 0;
  int _missiles = 3;
  double _barrRollCooldown = 0;
  bool _isBarrelRolling = false;
  double _barrRollTimer = 0;
  bool _isLocking = false;
  AdShip? _lockTarget;

  // Player ship
  double _px = 0.5, _py = 0.7;
  Offset _moveDir = Offset.zero;
  Offset _aimDir = Offset.zero;
  double _pAngle = 0;

  // Auto fire state
  double _autoFireTimer = 0;

  // Entities
  final List<AdShip> _enemies = [];
  final List<AdProjectile> _projs = [];
  final List<AdMine> _mines = [];
  final List<AdStar> _stars = [];
  final List<AdPowerUp> _powerUps = [];
  final List<AdParticle> _particles = [];

  final Random _rnd = Random();
  int _wave = 1;
  double _damageFlash = 0;

  @override
  void initState() {
    super.initState();
    _loadHS();
    _loop = AnimationController(vsync: this, duration: const Duration(seconds: 1))..repeat();
    _loop.addListener(_update);
    _buildStarfield();
  }

  void _buildStarfield() {
    for (int i = 0; i < 120; i++) {
      _stars.add(AdStar(x: _rnd.nextDouble(), y: _rnd.nextDouble(),
          r: 0.5 + _rnd.nextDouble() * 1.8, speed: 20 + _rnd.nextDouble() * 80));
    }
  }

  Future<void> _loadHS() async {
    final p = await SharedPreferences.getInstance();
    setState(() => _highScore = p.getInt('hi_score_astro_dogfight') ?? 0);
  }

  Future<void> _saveHS() async {
    if (_score > _highScore) {
      final p = await SharedPreferences.getInstance();
      await p.setInt('hi_score_astro_dogfight', _score);
      _highScore = _score;
    }
  }

  void _startGame() {
    setState(() {
      _playing = true; _over = false;
      _score = 0; _health = 100; _wave = 1; _missiles = 3;
      _shielded = false; _shieldTimer = 0;
      _barrRollCooldown = 0; _isBarrelRolling = false; _barrRollTimer = 0;
      _isLocking = false; _lockTarget = null;
      _px = 0.5; _py = 0.72;
      _moveDir = Offset.zero; _aimDir = Offset.zero; _pAngle = -pi / 2;
      _enemies.clear(); _projs.clear(); _mines.clear(); _powerUps.clear(); _particles.clear();
      _autoFireTimer = 0; _damageFlash = 0;
    });
    _spawnWave();
    HapticFeedback.mediumImpact();
  }

  void _spawnWave() {
    int count = 2 + _wave * 2;
    for (int i = 0; i < count; i++) {
      double typeR = _rnd.nextDouble();
      int type = _wave > 1 && typeR > 0.6 ? 1 : _wave > 3 && typeR > 0.85 ? 2 : 0;
      _enemies.add(AdShip(
        x: _rnd.nextDouble(), y: _rnd.nextDouble() * 0.5,
        type: type, hp: type == 0 ? 2 : type == 1 ? 5 : 3,
        fireCooldown: 1.0 + _rnd.nextDouble(),
      ));
    }
    // Bombers drop mines
    for (var e in _enemies.where((e) => e.type == 1)) {
      _mines.add(AdMine(e.x, e.y + 0.05));
    }
  }

  void _fireBarrelRoll() {
    if (_barrRollCooldown > 0) return;
    _isBarrelRolling = true; _barrRollTimer = 0.3; _barrRollCooldown = 2.0;
    HapticFeedback.mediumImpact();
    for (int i = 0; i < 12; i++) {
      double ang = _rnd.nextDouble() * 2 * pi;
      _particles.add(AdParticle(x: _px, y: _py, vx: cos(ang) * 0.2, vy: sin(ang) * 0.2,
          life: 0.4, color: _kNeonC, size: 4));
    }
  }

  void _fireMissile() {
    if (_missiles <= 0 || _lockTarget == null) return;
    _missiles--;
    _projs.add(AdProjectile(x: _px, y: _py, vx: 0, vy: -0.4, friendly: true, homing: true, target: _lockTarget));
    HapticFeedback.mediumImpact();
    _isLocking = false; _lockTarget = null;
  }

  void _update() {
    if (!_playing || _over) return;
    const double dt = 1 / 60;

    if (_damageFlash > 0) _damageFlash -= dt * 3;
    if (_barrRollCooldown > 0) _barrRollCooldown -= dt;
    if (_barrRollTimer > 0) { _barrRollTimer -= dt; if (_barrRollTimer <= 0) _isBarrelRolling = false; }
    if (_shieldTimer > 0) { _shieldTimer -= dt; if (_shieldTimer <= 0) _shielded = false; }

    // Move player
    double spd = 0.35 * dt;
    if (_moveDir.distance > 0.1) {
      _px = (_px + _moveDir.dx * spd).clamp(0.03, 0.97);
      _py = (_py + _moveDir.dy * spd).clamp(0.1, 0.9);
      _pAngle = atan2(_moveDir.dy, _moveDir.dx) + pi / 2;
    }

    // Auto-fire
    _autoFireTimer += dt;
    if (_autoFireTimer >= 0.18 && _aimDir.distance > 0.1) {
      _autoFireTimer = 0;
      double shotAngle = atan2(_aimDir.dy, _aimDir.dx);
      double spd2 = 0.6;
      _projs.add(AdProjectile(x: _px, y: _py, vx: cos(shotAngle) * spd2, vy: sin(shotAngle) * spd2, friendly: true));
      HapticFeedback.lightImpact();
    }

    // Scroll stars
    for (var s in _stars) {
      s.y += s.speed * dt / 800;
      if (s.y > 1) { s.y = 0; s.x = _rnd.nextDouble(); }
    }

    // Enemy movement and fire
    for (int i = _enemies.length - 1; i >= 0; i--) {
      var e = _enemies[i];
      if (e.isDying) { e.dieTimer -= dt; if (e.dieTimer <= 0) _enemies.removeAt(i); continue; }
      double dx = _px - e.x, dy = _py - e.y;
      double dist = sqrt(dx * dx + dy * dy);

      switch (e.type) {
        case 0: // Fighter — approaches player
          if (dist > 0) { e.x += dx / dist * 0.15 * dt; e.y += dy / dist * 0.12 * dt; }
          break;
        case 1: // Bomber — slow horizontal drift
          e.x += sin(DateTime.now().millisecondsSinceEpoch / 2000.0 + i) * 0.05 * dt;
          e.y += 0.03 * dt;
          break;
        case 2: // Ace — fast, dodges
          if (dist > 0) { e.x += dx / dist * 0.22 * dt; e.y += dy / dist * 0.18 * dt; }
          // Dodge incoming projectiles
          for (var p in _projs) {
            if (!p.friendly) continue;
            double pdx = e.x - p.x, pdy = e.y - p.y;
            double pdist = sqrt(pdx * pdx + pdy * pdy);
            if (pdist < 0.12) { e.x -= pdx / pdist * 0.08 * dt; e.y -= pdy / pdist * 0.08 * dt; }
          }
          break;
      }

      e.fireCooldown -= dt;
      if (e.fireCooldown <= 0 && dist < 0.65) {
        e.fireCooldown = e.type == 2 ? 0.8 : 1.5;
        double spd2 = 0.4;
        _projs.add(AdProjectile(x: e.x, y: e.y, vx: dx / dist * spd2, vy: dy / dist * spd2, friendly: false));
      }

      if (e.y > 1.1) _enemies.removeAt(i);
    }

    // Projectiles
    for (int i = _projs.length - 1; i >= 0; i--) {
      var p = _projs[i];
      p.life -= dt * 2;

      if (p.homing && p.target != null && !p.target!.isDying) {
        double dx = p.target!.x - p.x, dy = p.target!.y - p.y;
        double dist = sqrt(dx * dx + dy * dy);
        if (dist > 0) { p.vx = dx / dist * 0.5; p.vy = dy / dist * 0.5; }
      }

      p.x += p.vx * dt; p.y += p.vy * dt;

      if (p.life <= 0 || p.x < 0 || p.x > 1 || p.y < 0 || p.y > 1) {
        _projs.removeAt(i); continue;
      }

      if (p.friendly) {
        for (int j = _enemies.length - 1; j >= 0; j--) {
          var e = _enemies[j];
          if (e.isDying) continue;
          double dx = e.x - p.x, dy = e.y - p.y;
          if (sqrt(dx * dx + dy * dy) < 0.04) {
            e.hp -= p.homing ? 3 : 1;
            _spawnExpParts(e.x, e.y, e.type == 0 ? _kNeonY : e.type == 1 ? _kNeonO : _kNeonM);
            _projs.removeAt(i);
            if (e.hp <= 0) {
              e.isDying = true; e.dieTimer = 0.5;
              _score += e.type == 0 ? 100 : e.type == 1 ? 400 : 600;
              if (_rnd.nextDouble() < 0.25) _powerUps.add(AdPowerUp(e.x, e.y, _rnd.nextInt(3)));
            }
            break;
          }
        }
      } else {
        double dx = _px - p.x, dy = _py - p.y;
        if (sqrt(dx * dx + dy * dy) < 0.035) {
          _projs.removeAt(i);
          if (!_isBarrelRolling && !_shielded) _takeDmg(15);
          else if (_shielded) { _shielded = false; HapticFeedback.lightImpact(); }
        }
      }
    }

    // Mines
    for (int i = _mines.length - 1; i >= 0; i--) {
      var m = _mines[i];
      m.y += 0.04 * dt;
      double dx = _px - m.x, dy = _py - m.y;
      if (sqrt(dx * dx + dy * dy) < 0.04) {
        _mines.removeAt(i);
        if (!_isBarrelRolling) _takeDmg(25);
        _spawnExpParts(m.x, m.y, _kNeonO);
      }
      if (m.y > 1.1) _mines.removeAt(i);
    }

    // Power-ups
    for (int i = _powerUps.length - 1; i >= 0; i--) {
      var pu = _powerUps[i];
      pu.y += 0.06 * dt;
      double dx = _px - pu.x, dy = _py - pu.y;
      if (sqrt(dx * dx + dy * dy) < 0.05) {
        switch (pu.type) {
          case 0: _missiles = (_missiles + 2).clamp(0, 6); break;
          case 1: _health = (_health + 25).clamp(0, 100); break;
          case 2: _shielded = true; _shieldTimer = 5.0; break;
        }
        _powerUps.removeAt(i);
        HapticFeedback.lightImpact();
      } else if (pu.y > 1.1) _powerUps.removeAt(i);
    }

    // Particles
    for (int i = _particles.length - 1; i >= 0; i--) {
      var p = _particles[i];
      p.life -= dt; p.x += p.vx * dt; p.y += p.vy * dt;
      if (p.life <= 0) _particles.removeAt(i);
    }

    // Lock on nearest enemy
    if (_isLocking && _enemies.isNotEmpty) {
      AdShip? nearest;
      double nearDist = 999;
      for (var e in _enemies) {
        if (e.isDying) continue;
        double d = sqrt(pow(e.x - _px, 2) + pow(e.y - _py, 2));
        if (d < nearDist) { nearDist = d; nearest = e; }
      }
      _lockTarget = nearest;
    }

    // Wave clear
    if (_enemies.where((e) => !e.isDying).isEmpty && _mines.isEmpty) {
      _wave++;
      _health = (_health + 20).clamp(0, 100);
      _missiles = (_missiles + 1).clamp(0, 6);
      _spawnWave();
    }

    setState(() {});
  }

  void _spawnExpParts(double x, double y, Color c) {
    for (int i = 0; i < 20; i++) {
      double ang = _rnd.nextDouble() * 2 * pi;
      double spd = 0.1 + _rnd.nextDouble() * 0.3;
      _particles.add(AdParticle(x: x, y: y, vx: cos(ang) * spd, vy: sin(ang) * spd,
          life: 0.5 + _rnd.nextDouble() * 0.5, color: c, size: 3 + _rnd.nextDouble() * 6));
    }
  }

  void _takeDmg(double amt) {
    _health -= amt;
    _damageFlash = 1.0; HapticFeedback.heavyImpact();
    if (_health <= 0) { _health = 0; _over = true; _playing = false; _saveHS(); }
    setState(() {});
  }

  @override
  void dispose() { _loop.dispose(); super.dispose(); }

  @override
  Widget build(BuildContext context) {
    return Scaffold(backgroundColor: _kBg, body: Stack(children: [
      if (_playing || _over) Positioned.fill(child: CustomPaint(painter: AdPainter(
        px: _px, py: _py, pAngle: _pAngle, shielded: _shielded, isBarrelRolling: _isBarrelRolling,
        enemies: List.from(_enemies), projs: List.from(_projs), mines: List.from(_mines),
        stars: List.from(_stars), powerUps: List.from(_powerUps), particles: List.from(_particles),
        damageFlash: _damageFlash, lockTarget: _lockTarget,
      ))),

      // HUD
      if (_playing && !_over) ...[
        Positioned(top: 44, left: 16, child: Column(crossAxisAlignment: CrossAxisAlignment.start, children: [
          Text('WAVE $_wave', style: TextStyle(color: _kNeonY, fontSize: 22, fontWeight: FontWeight.w900,
            shadows: [Shadow(color: _kNeonY, blurRadius: 10)])),
          Text('SCORE: $_score', style: const TextStyle(color: Colors.white, fontSize: 16, fontWeight: FontWeight.bold)),
          Text('🚀 MISSILES: $_missiles', style: TextStyle(color: _kNeonR, fontSize: 14, fontWeight: FontWeight.bold)),
          if (_shielded) Text('🛡 SHIELD ACTIVE', style: TextStyle(color: _kNeonC, fontSize: 13)),
        ])),
        Positioned(top: 44, right: 16, child: Column(crossAxisAlignment: CrossAxisAlignment.end, children: [
          Row(children: [
            Icon(Icons.favorite, color: _kNeonR, size: 16),
            const SizedBox(width: 6),
            Container(width: 90, height: 10, decoration: BoxDecoration(color: Colors.white12, borderRadius: BorderRadius.circular(5)),
              child: FractionallySizedBox(widthFactor: (_health / 100).clamp(0, 1), alignment: Alignment.centerLeft,
                child: Container(decoration: BoxDecoration(color: _kNeonR, borderRadius: BorderRadius.circular(5),
                  boxShadow: [const BoxShadow(color: _kNeonR, blurRadius: 6)])))),
          ]),
          const SizedBox(height: 6),
          Text('BARREL ROLL: ${_barrRollCooldown > 0 ? '${_barrRollCooldown.toStringAsFixed(1)}s' : 'READY'}',
            style: TextStyle(color: _barrRollCooldown > 0 ? Colors.white38 : _kNeonG, fontSize: 12)),
        ])),
        // Controls
        Positioned(bottom: 16, left: 16, right: 16, child: SizedBox(height: 190, child: Row(
          mainAxisAlignment: MainAxisAlignment.spaceBetween, children: [
          VirtualJoystick(size: 120, baseColor: Colors.white12, knobColor: _kNeonY,
            onDirectionChanged: (dir) => setState(() => _moveDir = dir)),
          Column(mainAxisAlignment: MainAxisAlignment.center, children: [
            ActionButton(icon: Icons.rotate_right_rounded, color: _kNeonC, label: 'ROLL',
              onPressed: _fireBarrelRoll, size: 52),
            const SizedBox(height: 8),
            ActionButton(icon: Icons.gps_not_fixed_rounded, color: _kNeonR, label: _isLocking ? 'LOCK!' : 'LOCK',
              onPressStart: () => setState(() { _isLocking = true; }),
              onPressEnd: () { _fireMissile(); setState(() => _isLocking = false); },
              onPressed: () {}, size: 52),
          ]),
          VirtualJoystick(size: 120, baseColor: Colors.white12, knobColor: _kNeonR,
            onDirectionChanged: (dir) => setState(() => _aimDir = dir)),
        ]))),
      ],

      if (!_playing && !_over) buildArenaStartPrompt(
        context: context, gameName: 'ASTRO DOGFIGHT', subtitle: 'SPACE COMBAT',
        story: 'Pilot ACE-7 is the last surviving NEXDROID wingman. '
            'The Galactic Insurgency has deployed three fleets. '
            'Destroy fighters, bomb bombers, and outmaneuver ace pilots!',
        controls: 'Left stick: Fly ship • Right stick: Aim auto-cannon\n'
            'BARREL ROLL: dodge (2s cooldown, invincible during)\n'
            'LOCK: Hold to lock on enemy, release to fire homing missile',
        accentColor: _kNeonY, secondColor: _kNeonC,
        highScore: _highScore, onPlay: _startGame,
      ),
      if (_over) buildArenaGameOver(
        context: context, gameName: 'ASTRO DOGFIGHT', score: _score, highScore: _highScore,
        extra: 'WAVE: $_wave', accentColor: _kNeonY,
        onRetry: _startGame,
        onMenu: () => setState(() { _over = false; _playing = false; }),
      ),
    ]));
  }
}

// ============================================================
// ASTRO DOGFIGHT PAINTER
// ============================================================
class AdPainter extends CustomPainter {
  final double px, py, pAngle, damageFlash;
  final bool shielded, isBarrelRolling;
  final AdShip? lockTarget;
  final List<AdShip> enemies;
  final List<AdProjectile> projs;
  final List<AdMine> mines;
  final List<AdStar> stars;
  final List<AdPowerUp> powerUps;
  final List<AdParticle> particles;

  AdPainter({required this.px, required this.py, required this.pAngle, required this.shielded,
    required this.isBarrelRolling, required this.enemies, required this.projs, required this.mines,
    required this.stars, required this.powerUps, required this.particles, required this.damageFlash,
    this.lockTarget});

  @override
  void paint(Canvas canvas, Size size) {
    canvas.drawRect(Rect.fromLTWH(0, 0, size.width, size.height), Paint()..color = const Color(0xFF01010A));

    // Stars
    for (var s in stars) {
      canvas.drawCircle(Offset(s.x * size.width, s.y * size.height), s.r,
          Paint()..color = Colors.white.withValues(alpha: 0.4 + s.r * 0.2));
    }

    // Mines
    for (var m in mines) {
      canvas.drawCircle(Offset(m.x * size.width, m.y * size.height), 8,
          Paint()..color = _kNeonO.withValues(alpha: 0.7)..maskFilter = const MaskFilter.blur(BlurStyle.normal, 4));
      canvas.drawCircle(Offset(m.x * size.width, m.y * size.height), 8,
          Paint()..color = _kNeonO..style = PaintingStyle.stroke..strokeWidth = 1.5);
      // Cross
      canvas.drawLine(Offset(m.x * size.width - 5, m.y * size.height), Offset(m.x * size.width + 5, m.y * size.height),
          Paint()..color = Colors.white..strokeWidth = 1.5);
      canvas.drawLine(Offset(m.x * size.width, m.y * size.height - 5), Offset(m.x * size.width, m.y * size.height + 5),
          Paint()..color = Colors.white..strokeWidth = 1.5);
    }

    // Power-ups
    for (var pu in powerUps) {
      Color c = pu.type == 0 ? _kNeonR : pu.type == 1 ? _kNeonG : _kNeonC;
      canvas.drawCircle(Offset(pu.x * size.width, pu.y * size.height), 12,
          Paint()..color = c.withValues(alpha: 0.25)..maskFilter = const MaskFilter.blur(BlurStyle.normal, 8));
      canvas.drawCircle(Offset(pu.x * size.width, pu.y * size.height), 12,
          Paint()..color = c..style = PaintingStyle.stroke..strokeWidth = 2);
    }

    // Enemy ships
    for (var e in enemies) {
      Color c = e.type == 0 ? _kNeonR : e.type == 1 ? _kNeonO : _kNeonM;
      double r = e.type == 1 ? 18 : 12;
      double alpha = e.isDying ? e.dieTimer * 2 : 1.0;
      double ex = e.x * size.width, ey = e.y * size.height;

      canvas.save();
      canvas.translate(ex, ey);
      canvas.rotate(e.angle);

      Paint glow = Paint()..color = c.withValues(alpha: alpha * 0.4)..maskFilter = const MaskFilter.blur(BlurStyle.normal, 10);
      Paint fill = Paint()..color = c.withValues(alpha: alpha * 0.7);
      Paint outline = Paint()..color = c.withValues(alpha: alpha)..style = PaintingStyle.stroke..strokeWidth = 1.5;

      if (e.type == 1) {
        // Bomber — wide diamond
        Path bPath = Path()
          ..moveTo(0, -r * 0.7) ..lineTo(r * 1.5, 0)
          ..lineTo(0, r * 0.7) ..lineTo(-r * 1.5, 0) ..close();
        canvas.drawPath(bPath, glow); canvas.drawPath(bPath, fill); canvas.drawPath(bPath, outline);
      } else {
        // Fighter/Ace — angular arrow shape
        Path sPath = Path()
          ..moveTo(0, -r) ..lineTo(r * 0.7, r * 0.6)
          ..lineTo(0, r * 0.2) ..lineTo(-r * 0.7, r * 0.6) ..close();
        canvas.drawPath(sPath, glow); canvas.drawPath(sPath, fill); canvas.drawPath(sPath, outline);
        if (e.type == 2) {
          // Ace has extra wing stripes
          canvas.drawLine(const Offset(-4, 0), const Offset(4, 0), Paint()..color = Colors.white..strokeWidth = 1.5);
        }
      }

      // Lock indicator
      if (lockTarget == e) {
        canvas.drawRect(Rect.fromCenter(center: Offset.zero, width: r * 3, height: r * 3),
            Paint()..color = _kNeonR..style = PaintingStyle.stroke..strokeWidth = 2);
      }

      canvas.restore();

      // HP bar
      if (e.maxHp > 1 && !e.isDying) {
        double bw = r * 2.5;
        canvas.drawRect(Rect.fromLTWH(ex - bw / 2, ey - r - 10, bw, 4), Paint()..color = Colors.black45);
        canvas.drawRect(Rect.fromLTWH(ex - bw / 2, ey - r - 10, bw * e.hp / e.maxHp, 4), Paint()..color = c);
      }
    }

    // Projectiles
    for (var p in projs) {
      Color c = p.friendly ? (p.homing ? _kNeonR : _kNeonY) : _kNeonO;
      canvas.drawLine(
        Offset(p.x * size.width, p.y * size.height),
        Offset((p.x - p.vx * 0.03) * size.width, (p.y - p.vy * 0.03) * size.height),
        Paint()..color = c..strokeWidth = p.homing ? 4 : 2..strokeCap = StrokeCap.round
          ..maskFilter = MaskFilter.blur(BlurStyle.normal, p.homing ? 6 : 2),
      );
    }

    // Player ship
    double sx = px * size.width, sy = py * size.height;
    canvas.save();
    canvas.translate(sx, sy);
    canvas.rotate(pAngle);

    Paint pGlow = Paint()..color = _kNeonY.withValues(alpha: isBarrelRolling ? 0.6 : 0.3)
      ..maskFilter = const MaskFilter.blur(BlurStyle.normal, 12);
    Paint pFill = Paint()..color = isBarrelRolling ? Colors.white : _kNeonY.withValues(alpha: 0.85);
    Paint pOut = Paint()..color = _kNeonY..style = PaintingStyle.stroke..strokeWidth = 2;

    Path shipPath = Path()
      ..moveTo(0, -20) ..lineTo(14, 12)
      ..lineTo(6, 6) ..lineTo(0, 10) ..lineTo(-6, 6)
      ..lineTo(-14, 12) ..close();
    canvas.drawPath(shipPath, pGlow);
    canvas.drawPath(shipPath, pFill);
    canvas.drawPath(shipPath, pOut);

    // Shield visual
    if (shielded) {
      canvas.drawCircle(Offset.zero, 22,
          Paint()..color = _kNeonC.withValues(alpha: 0.3)..maskFilter = const MaskFilter.blur(BlurStyle.normal, 8));
      canvas.drawCircle(Offset.zero, 22,
          Paint()..color = _kNeonC..style = PaintingStyle.stroke..strokeWidth = 2);
    }

    canvas.restore();

    // Thrust trail
    for (int i = 0; i < 8; i++) {
      canvas.drawCircle(
        Offset(sx + (Random().nextDouble() - 0.5) * 8, sy + 20 + i * 3),
        2.0 - i * 0.2,
        Paint()..color = _kNeonO.withValues(alpha: (1 - i / 8) * 0.7)
          ..maskFilter = const MaskFilter.blur(BlurStyle.normal, 2),
      );
    }

    // Particles
    for (var p in particles) {
      canvas.drawCircle(Offset(p.x * size.width, p.y * size.height), p.size,
          Paint()..color = p.color.withValues(alpha: p.life.clamp(0, 1))
            ..maskFilter = MaskFilter.blur(BlurStyle.normal, p.size * 0.3));
    }

    // Damage flash
    if (damageFlash > 0) {
      canvas.drawRect(Rect.fromLTWH(0, 0, size.width, size.height),
          Paint()..color = _kNeonR.withValues(alpha: damageFlash * 0.38));
    }
  }

  @override
  bool shouldRepaint(covariant CustomPainter old) => true;
}

// ============================================================
// PIXEL BRAWL — DATA
// ============================================================
enum PbAttack { none, punch, kick, special, block }

class PbFighterState {
  double x, y;
  double hp, maxHp;
  bool facingRight;
  PbAttack currentAttack;
  double attackTimer, attackCooldown;
  bool isBlocking, isJumping;
  double vy;
  int comboCount;
  double comboTimer;
  String name;
  Color color, darkColor;

  PbFighterState({required this.x, required this.y, required this.name,
    required this.color, required this.darkColor, this.facingRight = true})
      : hp = 100, maxHp = 100, currentAttack = PbAttack.none, attackTimer = 0,
        attackCooldown = 0, isBlocking = false, isJumping = false, vy = 0,
        comboCount = 0, comboTimer = 0;
}

class PbParticle { double x, y, vx, vy, life; Color color; double size;
  PbParticle({required this.x, required this.y, required this.vx, required this.vy,
    required this.life, required this.color, this.size = 3.0}); }

// ============================================================
// PIXEL BRAWL GAME
// ============================================================
class PixelBrawlGame extends StatefulWidget {
  const PixelBrawlGame({Key? key}) : super(key: key);
  @override
  State<PixelBrawlGame> createState() => _PixelBrawlGameState();
}

class _PixelBrawlGameState extends State<PixelBrawlGame> with TickerProviderStateMixin {
  late AnimationController _loop;
  bool _playing = false, _over = false;
  int _score = 0, _highScore = 0;
  int _playerWins = 0, _cpuWins = 0;
  int _round = 1;
  bool _roundOver = false;
  String _roundResult = '';
  double _roundResultTimer = 0;
  bool _showRoundStart = true;
  double _roundStartTimer = 2.0;
  String _difficulty = 'Medium';
  double _specialCooldown = 0;

  late PbFighterState _player;
  late PbFighterState _cpu;
  final List<PbParticle> _particles = [];
  final Random _rnd = Random();

  @override
  void initState() {
    super.initState();
    _loadHS();
    _loop = AnimationController(vsync: this, duration: const Duration(seconds: 1))..repeat();
    _loop.addListener(_update);
  }

  Future<void> _loadHS() async {
    final p = await SharedPreferences.getInstance();
    setState(() => _highScore = p.getInt('hi_score_pixel_brawl') ?? 0);
  }

  Future<void> _saveHS() async {
    if (_score > _highScore) {
      final p = await SharedPreferences.getInstance();
      await p.setInt('hi_score_pixel_brawl', _score);
      _highScore = _score;
    }
  }

  void _startGame() {
    setState(() {
      _playing = true; _over = false;
      _score = 0; _playerWins = 0; _cpuWins = 0; _round = 1;
      _roundOver = false; _roundResult = ''; _roundResultTimer = 0;
      _showRoundStart = true; _roundStartTimer = 2.0; _specialCooldown = 0;
      _initFighters();
      _particles.clear();
    });
    HapticFeedback.mediumImpact();
  }

  void _initFighters() {
    _player = PbFighterState(x: 0.15, y: 0.0, name: 'STRIKER', color: _kNeonC, darkColor: const Color(0xFF003344), facingRight: true);
    _cpu = PbFighterState(x: 0.75, y: 0.0, name: 'PHANTOM', color: _kNeonM, darkColor: const Color(0xFF330022), facingRight: false);
  }

  void _doPlayerAttack(PbAttack atk) {
    if (_roundOver || _showRoundStart) return;
    if (_player.attackCooldown > 0 || _player.currentAttack != PbAttack.none) return;
    if (atk == PbAttack.special && _specialCooldown > 0) return;
    _player.currentAttack = atk;
    _player.attackTimer = atk == PbAttack.punch ? 0.2 : atk == PbAttack.kick ? 0.3 : atk == PbAttack.special ? 0.5 : 0.4;
    _player.attackCooldown = atk == PbAttack.punch ? 0.3 : atk == PbAttack.kick ? 0.5 : atk == PbAttack.special ? 1.2 : 0.2;
    if (atk == PbAttack.special) _specialCooldown = 4.0;
    HapticFeedback.mediumImpact();

    // Check hit
    double dist = (_cpu.x - _player.x).abs();
    double hitRange = atk == PbAttack.kick ? 0.22 : atk == PbAttack.special ? 0.4 : 0.18;
    if (dist < hitRange) {
      double dmg = atk == PbAttack.punch ? 8 : atk == PbAttack.kick ? 14 : atk == PbAttack.special ? 30 : 0;
      if (_player.comboCount > 0) dmg *= 1.0 + _player.comboCount * 0.2;
      if (!_cpu.isBlocking) {
        _cpu.hp -= dmg;
        _player.comboCount++;
        _player.comboTimer = 1.5;
        _score += dmg.toInt() * (1 + _player.comboCount);
        _spawnHitParticles(_cpu.x, 0.55, _kNeonM);
        HapticFeedback.heavyImpact();
        if (_cpu.hp <= 0) { _cpu.hp = 0; _endRound(playerWin: true); }
      } else {
        // Blocked
        _spawnHitParticles(_cpu.x, 0.55, Colors.grey);
      }
    }
    setState(() {});
  }

  void _setBlock(bool blocking) {
    setState(() => _player.isBlocking = blocking);
  }

  void _playerJump() {
    if (!_player.isJumping && _player.y == 0) {
      _player.vy = -0.8; _player.isJumping = true;
      HapticFeedback.lightImpact();
    }
  }

  void _spawnHitParticles(double x, double y, Color c) {
    for (int i = 0; i < 12; i++) {
      double ang = _rnd.nextDouble() * 2 * pi;
      _particles.add(PbParticle(x: x, y: y, vx: cos(ang) * 0.06, vy: sin(ang) * 0.06 - 0.1,
          life: 0.4, color: c, size: 4 + _rnd.nextDouble() * 5));
    }
  }

  void _endRound({required bool playerWin}) {
    if (_roundOver) return;
    _roundOver = true;
    if (playerWin) { _playerWins++; _roundResult = 'ROUND $_round — STRIKER WINS!'; }
    else { _cpuWins++; _roundResult = 'ROUND $_round — PHANTOM WINS!'; }
    _roundResultTimer = 2.5;
    HapticFeedback.heavyImpact();
  }

  void _update() {
    if (!_playing || _over) return;
    const double dt = 1 / 60;

    if (_showRoundStart) {
      _roundStartTimer -= dt;
      if (_roundStartTimer <= 0) { _showRoundStart = false; _roundStartTimer = 0; }
      setState(() {}); return;
    }

    if (_roundOver) {
      _roundResultTimer -= dt;
      if (_roundResultTimer <= 0) {
        if (_playerWins >= 2) { _over = true; _playing = false; _saveHS(); }
        else if (_cpuWins >= 2) { _over = true; _playing = false; _saveHS(); }
        else {
          _round++;
          _initFighters();
          _roundOver = false;
          _showRoundStart = true;
          _roundStartTimer = 2.0;
          _specialCooldown = 0;
        }
        setState(() {}); return;
      }
      setState(() {}); return;
    }

    if (_specialCooldown > 0) _specialCooldown -= dt;

    // Player physics
    if (_player.isJumping) {
      _player.y += _player.vy * dt;
      _player.vy += 4.0 * dt;
      if (_player.y >= 0) { _player.y = 0; _player.vy = 0; _player.isJumping = false; }
    }

    // Player combo decay
    if (_player.comboTimer > 0) { _player.comboTimer -= dt; if (_player.comboTimer <= 0) _player.comboCount = 0; }
    if (_player.attackCooldown > 0) _player.attackCooldown -= dt;
    if (_player.attackTimer > 0) { _player.attackTimer -= dt; if (_player.attackTimer <= 0) _player.currentAttack = PbAttack.none; }

    // CPU AI
    if (_cpu.attackCooldown > 0) _cpu.attackCooldown -= dt;
    if (_cpu.attackTimer > 0) { _cpu.attackTimer -= dt; if (_cpu.attackTimer <= 0) _cpu.currentAttack = PbAttack.none; }

    double dist = (_player.x - _cpu.x).abs();
    _cpu.facingRight = _player.x > _cpu.x;

    // CPU moves towards player
    double aiSpd = _difficulty == 'Easy' ? 0.07 : _difficulty == 'Hard' ? 0.14 : 0.10;
    if (dist > 0.15) {
      _cpu.x += (_player.x - _cpu.x) / dist * aiSpd * dt;
    } else if (dist < 0.08 && _rnd.nextDouble() < 0.05) {
      _cpu.x -= (_player.x - _cpu.x) / dist * aiSpd * 0.5 * dt;
    }

    // CPU attacks when in range
    if (dist < 0.2 && _cpu.attackCooldown <= 0 && _cpu.currentAttack == PbAttack.none) {
      double r = _rnd.nextDouble();
      double aiDecision = _difficulty == 'Easy' ? 0.3 : _difficulty == 'Hard' ? 0.7 : 0.5;
      if (r < 0.1) {
        // CPU blocks
        _cpu.isBlocking = true;
        _cpu.attackCooldown = 0.5;
      } else if (r < aiDecision) {
        PbAttack cpuAtk = _rnd.nextDouble() > 0.5 ? PbAttack.kick : PbAttack.punch;
        if (_rnd.nextDouble() < 0.15 && _cpu.comboTimer <= 0) cpuAtk = PbAttack.special;
        _cpu.currentAttack = cpuAtk;
        _cpu.attackTimer = cpuAtk == PbAttack.punch ? 0.2 : cpuAtk == PbAttack.kick ? 0.3 : 0.5;
        _cpu.attackCooldown = cpuAtk == PbAttack.punch ? 0.4 : cpuAtk == PbAttack.kick ? 0.6 : 1.5;
        // CPU deals damage to player
        double dmg = cpuAtk == PbAttack.punch ? 6 : cpuAtk == PbAttack.kick ? 10 : 25;
        if (_difficulty == 'Easy') dmg *= 0.6;
        if (_difficulty == 'Hard') dmg *= 1.5;
        if (!_player.isBlocking) {
          _player.hp -= dmg;
          _spawnHitParticles(_player.x, 0.55, _kNeonC);
          HapticFeedback.mediumImpact();
          if (_player.hp <= 0) { _player.hp = 0; _endRound(playerWin: false); }
        } else {
          _spawnHitParticles(_player.x, 0.55, Colors.grey);
        }
      } else {
        _cpu.isBlocking = false;
      }
    } else {
      _cpu.isBlocking = false;
    }

    // Particles
    for (int i = _particles.length - 1; i >= 0; i--) {
      var p = _particles[i];
      p.life -= dt; p.x += p.vx; p.y += p.vy; p.vy += 0.01;
      if (p.life <= 0) _particles.removeAt(i);
    }

    setState(() {});
  }

  @override
  void dispose() { _loop.dispose(); super.dispose(); }

  @override
  Widget build(BuildContext context) {
    return Scaffold(backgroundColor: _kBg, body: Stack(children: [
      if (_playing || _over) Positioned.fill(child: CustomPaint(painter: PbPainter(
        player: _player, cpu: _cpu, particles: List.from(_particles),
        playerWins: _playerWins, cpuWins: _cpuWins, round: _round,
        showRoundStart: _showRoundStart, roundResult: _roundResult,
        roundResultTimer: _roundResultTimer, roundOver: _roundOver,
      ))),

      // Controls
      if (_playing && !_over && !_showRoundStart && !_roundOver) ...[
        // Attack buttons (right side)
        Positioned(bottom: 20, right: 16, child: Column(mainAxisSize: MainAxisSize.min, children: [
          Row(children: [
            ActionButton(icon: Icons.sports_mma_rounded, color: _kNeonY, label: 'PUNCH',
              onPressed: () => _doPlayerAttack(PbAttack.punch), size: 58),
            const SizedBox(width: 8),
            ActionButton(icon: Icons.sports_kabaddi_rounded, color: _kNeonO, label: 'KICK',
              onPressed: () => _doPlayerAttack(PbAttack.kick), size: 58),
          ]),
          const SizedBox(height: 10),
          Row(children: [
            ActionButton(icon: Icons.electric_bolt_rounded, color: _kNeonM,
              label: _specialCooldown > 0 ? '${_specialCooldown.toStringAsFixed(1)}s' : 'SPECIAL',
              onPressed: () => _doPlayerAttack(PbAttack.special), size: 58),
            const SizedBox(width: 8),
            ActionButton(icon: Icons.shield_rounded, color: _kNeonC, label: 'BLOCK',
              onPressStart: () => _setBlock(true), onPressEnd: () => _setBlock(false),
              onPressed: () {}, size: 58),
          ]),
        ])),
        // Movement (left side)
        Positioned(bottom: 20, left: 16, child: Column(mainAxisSize: MainAxisSize.min, children: [
          ActionButton(icon: Icons.arrow_upward_rounded, color: _kNeonG, label: 'JUMP',
            onPressed: _playerJump, size: 52),
          const SizedBox(height: 8),
          Row(children: [
            ActionButton(icon: Icons.arrow_back_rounded, color: Colors.white70, label: 'LEFT',
              onPressed: () => setState(() => _player.x = (_player.x - 0.06).clamp(0.05, _cpu.x - 0.12)), size: 48),
            const SizedBox(width: 8),
            ActionButton(icon: Icons.arrow_forward_rounded, color: Colors.white70, label: 'RIGHT',
              onPressed: () => setState(() => _player.x = (_player.x + 0.06).clamp(0.05, _cpu.x - 0.08)), size: 48),
          ]),
        ])),
        // HUD top
        Positioned(top: 44, left: 16, right: 16, child: Row(children: [
          Expanded(child: Column(crossAxisAlignment: CrossAxisAlignment.start, children: [
            Text(_player.name, style: TextStyle(color: _kNeonC, fontSize: 14, fontWeight: FontWeight.bold)),
            _pbHpBar(_player.hp / _player.maxHp, _kNeonC),
            Text('COMBO x${_player.comboCount}', style: TextStyle(color: _kNeonY, fontSize: 12)),
          ])),
          Column(children: [
            Text('ROUND $_round', style: const TextStyle(color: Colors.white, fontSize: 16, fontWeight: FontWeight.bold)),
            Row(children: [
              ...List.generate(_playerWins, (_) => Icon(Icons.star_rounded, color: _kNeonC, size: 14)),
              const Text(' vs ', style: TextStyle(color: Colors.white38, fontSize: 12)),
              ...List.generate(_cpuWins, (_) => Icon(Icons.star_rounded, color: _kNeonM, size: 14)),
            ]),
          ]),
          Expanded(child: Column(crossAxisAlignment: CrossAxisAlignment.end, children: [
            Text(_cpu.name, style: TextStyle(color: _kNeonM, fontSize: 14, fontWeight: FontWeight.bold)),
            _pbHpBar(_cpu.hp / _cpu.maxHp, _kNeonM),
          ])),
        ])),
      ],

      // Round start overlay
      if (_playing && _showRoundStart)
        Center(child: Text('ROUND $_round\nFIGHT!', textAlign: TextAlign.center, style: TextStyle(
          color: _kNeonY, fontSize: 42, fontWeight: FontWeight.w900, letterSpacing: 4,
          shadows: [Shadow(color: _kNeonY, blurRadius: 20)]))),

      // Round result overlay
      if (_playing && _roundOver && _roundResultTimer > 1.5)
        Center(child: Text(_roundResult, textAlign: TextAlign.center, style: TextStyle(
          color: _kNeonO, fontSize: 28, fontWeight: FontWeight.w900, letterSpacing: 2,
          shadows: [Shadow(color: _kNeonO, blurRadius: 15)]))),

      if (!_playing && !_over) buildArenaStartPrompt(
        context: context, gameName: 'PIXEL BRAWL', subtitle: '2D FIGHTING ARENA',
        story: 'STRIKER vs PHANTOM — neon street fighters battling for supremacy. '
            'Best of 3 rounds. Chain combos, block punches, unleash special moves!',
        controls: 'PUNCH: Fast low damage • KICK: Medium damage\n'
            'SPECIAL: High damage (4s cooldown) • BLOCK: Reduce damage taken\n'
            'LEFT/RIGHT: Move • JUMP: Avoid attacks',
        accentColor: _kNeonM, secondColor: _kNeonC,
        highScore: _highScore, onPlay: _startGame,
        extraInfo: Row(mainAxisAlignment: MainAxisAlignment.center, children: [
          Text('DIFFICULTY: ', style: const TextStyle(color: Colors.white54, fontSize: 13)),
          ...[('EASY', Colors.green), ('MEDIUM', _kNeonO), ('HARD', _kNeonR)].map((d) =>
            Padding(padding: const EdgeInsets.symmetric(horizontal: 4), child: ElevatedButton(
              style: ElevatedButton.styleFrom(backgroundColor: _difficulty == d.$1 ? d.$2.withValues(alpha: 0.3) : Colors.transparent,
                side: BorderSide(color: d.$2), padding: const EdgeInsets.symmetric(horizontal: 10, vertical: 6)),
              onPressed: () => setState(() => _difficulty = d.$1),
              child: Text(d.$1, style: TextStyle(color: d.$2, fontSize: 12)),
            ))),
        ]),
      ),
      if (_over) buildArenaGameOver(
        context: context, gameName: 'PIXEL BRAWL', score: _score, highScore: _highScore,
        extra: 'ROUNDS WON: $_playerWins', accentColor: _kNeonM,
        onRetry: _startGame,
        onMenu: () => setState(() { _over = false; _playing = false; }),
      ),
    ]));
  }

  Widget _pbHpBar(double frac, Color c) => Container(
    width: 130, height: 8, decoration: BoxDecoration(color: Colors.white12, borderRadius: BorderRadius.circular(4)),
    child: FractionallySizedBox(widthFactor: frac.clamp(0, 1), alignment: Alignment.centerLeft,
      child: Container(decoration: BoxDecoration(color: c, borderRadius: BorderRadius.circular(4),
        boxShadow: [BoxShadow(color: c, blurRadius: 4)]))));
}

// ============================================================
// PIXEL BRAWL PAINTER
// ============================================================
class PbPainter extends CustomPainter {
  final PbFighterState player, cpu;
  final List<PbParticle> particles;
  final int playerWins, cpuWins, round;
  final bool showRoundStart, roundOver;
  final String roundResult;
  final double roundResultTimer;

  PbPainter({required this.player, required this.cpu, required this.particles,
    required this.playerWins, required this.cpuWins, required this.round,
    required this.showRoundStart, required this.roundOver, required this.roundResult,
    required this.roundResultTimer});

  @override
  void paint(Canvas canvas, Size size) {
    // Retro arena background
    canvas.drawRect(Rect.fromLTWH(0, 0, size.width, size.height),
        Paint()..color = const Color(0xFF080418));

    // Scanlines
    for (int i = 0; i < size.height ~/ 4; i++) {
      canvas.drawLine(Offset(0, i * 4 + 2), Offset(size.width, i * 4 + 2),
          Paint()..color = Colors.black.withValues(alpha: 0.25)..strokeWidth = 1.5);
    }

    // Arena floor
    double groundY = size.height * 0.78;
    canvas.drawRect(Rect.fromLTRB(0, groundY, size.width, size.height),
        Paint()..color = const Color(0xFF120B28));

    // Floor grid
    for (int i = 0; i < 10; i++) {
      double y = groundY + i * (size.height - groundY) / 8;
      canvas.drawLine(Offset(0, y), Offset(size.width, y),
          Paint()..color = _kNeonM.withValues(alpha: 0.06 + i * 0.01)..strokeWidth = 0.5);
    }
    canvas.drawLine(Offset(0, groundY), Offset(size.width, groundY),
        Paint()..color = _kNeonM.withValues(alpha: 0.5)..strokeWidth = 2
          ..maskFilter = const MaskFilter.blur(BlurStyle.normal, 3));

    // Background neon pillars
    for (int i = 0; i < 4; i++) {
      double px = 30 + i * size.width / 3.5;
      canvas.drawRect(Rect.fromLTWH(px, size.height * 0.1, 12, groundY - size.height * 0.1),
          Paint()..color = const Color(0xFF1A0D2E));
      canvas.drawRect(Rect.fromLTWH(px, size.height * 0.1, 12, groundY - size.height * 0.1),
          Paint()..color = (i % 2 == 0 ? _kNeonC : _kNeonM).withValues(alpha: 0.25)
            ..style = PaintingStyle.stroke..strokeWidth = 1.5);
    }

    // Draw fighters
    _drawFighter(canvas, size, player, groundY);
    _drawFighter(canvas, size, cpu, groundY);

    // Particles
    for (var p in particles) {
      canvas.drawRect(Rect.fromCenter(center: Offset(p.x * size.width, p.y * size.height),
          width: p.size, height: p.size),
          Paint()..color = p.color.withValues(alpha: p.life.clamp(0, 1))
            ..maskFilter = MaskFilter.blur(BlurStyle.normal, p.size * 0.3));
    }
  }

  void _drawFighter(Canvas canvas, Size size, PbFighterState f, double groundY) {
    double fx = f.x * size.width;
    double fy = groundY + f.y * size.height * 0.15;
    double fh = 70; double fw = 28;
    bool attacking = f.currentAttack != PbAttack.none && f.currentAttack != PbAttack.block;

    // Glow
    canvas.drawRRect(RRect.fromRectAndRadius(Rect.fromLTWH(fx - fw / 2 - 4, fy - fh - 4, fw + 8, fh + 8),
        const Radius.circular(6)), Paint()..color = f.color.withValues(alpha: 0.25)
      ..maskFilter = const MaskFilter.blur(BlurStyle.normal, 10));

    // Body (pixelated rectangle style)
    canvas.drawRect(Rect.fromLTWH(fx - fw / 2, fy - fh, fw, fh * 0.55), Paint()..color = f.color.withValues(alpha: 0.8));
    canvas.drawRect(Rect.fromLTWH(fx - fw / 2 + 2, fy - fh + 2, fw - 4, fh * 0.55 - 4), Paint()..color = f.darkColor);

    // Head
    canvas.drawRect(Rect.fromLTWH(fx - 10, fy - fh - 18, 20, 18), Paint()..color = f.color.withValues(alpha: 0.9));
    // Visor
    canvas.drawRect(Rect.fromLTWH(fx - 7, fy - fh - 13, 14, 6), Paint()..color = Colors.white.withValues(alpha: 0.6)
      ..maskFilter = const MaskFilter.blur(BlurStyle.normal, 3));

    // Legs
    double legOffset = attacking ? 4 : 0;
    canvas.drawRect(Rect.fromLTWH(fx - fw / 2 + 2, fy - fh * 0.44, fw / 2 - 2, fh * 0.44), Paint()..color = f.darkColor);
    canvas.drawRect(Rect.fromLTWH(fx + 2, fy - fh * 0.44, fw / 2 - 2, fh * 0.44 + legOffset), Paint()..color = f.darkColor);

    // Attack effect
    if (attacking) {
      double armDir = f.facingRight ? 1 : -1;
      double armLen = f.currentAttack == PbAttack.kick ? 50 : f.currentAttack == PbAttack.special ? 70 : 38;
      double armY = f.currentAttack == PbAttack.kick ? fy - fh * 0.2 : fy - fh * 0.65;
      Color attackColor = f.currentAttack == PbAttack.special ? _kNeonY : f.color;
      canvas.drawLine(Offset(fx, armY), Offset(fx + armDir * armLen, armY),
          Paint()..color = attackColor..strokeWidth = 5..strokeCap = StrokeCap.round
            ..maskFilter = MaskFilter.blur(BlurStyle.normal, f.currentAttack == PbAttack.special ? 12 : 4));
    }

    // Block effect
    if (f.isBlocking) {
      canvas.drawOval(Rect.fromCenter(center: Offset(fx + (f.facingRight ? 16 : -16), fy - fh * 0.6), width: 24, height: 32),
          Paint()..color = f.color.withValues(alpha: 0.5)..maskFilter = const MaskFilter.blur(BlurStyle.normal, 6));
    }

    // Outline
    canvas.drawRect(Rect.fromLTWH(fx - fw / 2, fy - fh, fw, fh * 0.55),
        Paint()..color = f.color..style = PaintingStyle.stroke..strokeWidth = 1.5);
  }

  @override
  bool shouldRepaint(covariant CustomPainter old) => true;
}

// ============================================================
// DRIFT KINGS — DATA
// ============================================================
class DkCheckpoint { double x, y; bool passed; DkCheckpoint(this.x, this.y) : passed = false; }
class DkAICar { double x, y, angle, speed, targetProgress; int position;
  DkAICar({required this.x, required this.y, required this.angle, this.speed = 0.7, this.targetProgress = 0}) : position = 1; }
class DkParticle { double x, y, vx, vy, life; Color color; double size;
  DkParticle({required this.x, required this.y, required this.vx, required this.vy,
    required this.life, required this.color, this.size = 3.0}); }

// ============================================================
// DRIFT KINGS GAME
// ============================================================
class DriftKingsGame extends StatefulWidget {
  const DriftKingsGame({Key? key}) : super(key: key);
  @override
  State<DriftKingsGame> createState() => _DriftKingsGameState();
}

class _DriftKingsGameState extends State<DriftKingsGame> with TickerProviderStateMixin {
  late AnimationController _loop;
  bool _playing = false, _over = false;
  int _score = 0, _highScore = 0;
  int _lap = 0, _totalLaps = 3, _position = 1;
  int _nitros = 3;
  bool _isGassing = false, _isBraking = false, _isNitroing = false;
  double _nitroTimer = 0;
  double _driftPoints = 0, _driftMult = 1.0;
  double _damageFlash = 0;
  bool _raceOver = false;
  String _raceResult = '';

  // Player car
  double _px = 0.5, _py = 0.5; // normalized
  double _pAngle = 0; // radians
  double _pSpeed = 0;
  double _steerInput = 0;
  double _driftAngle = 0;

  // Track
  final List<Offset> _trackPath = [];
  final List<DkCheckpoint> _checkpoints = [];
  final List<DkAICar> _aiCars = [];
  final List<DkParticle> _particles = [];

  int _nextCheckIdx = 0;
  double _lapTime = 0;
  double _bestLapTime = 999;

  final Random _rnd = Random();

  @override
  void initState() {
    super.initState();
    _loadHS();
    _loop = AnimationController(vsync: this, duration: const Duration(seconds: 1))..repeat();
    _loop.addListener(_update);
    _buildTrack();
  }

  void _buildTrack() {
    _trackPath.clear();
    // Oval track (normalized 0-1 coordinates)
    int pts = 48;
    for (int i = 0; i < pts; i++) {
      double t = i / pts * 2 * pi;
      double x = 0.5 + 0.35 * cos(t);
      double y = 0.5 + 0.22 * sin(t);
      _trackPath.add(Offset(x, y));
    }

    // Checkpoints
    _checkpoints.clear();
    for (int i = 0; i < 4; i++) {
      double t = i / 4 * 2 * pi;
      _checkpoints.add(DkCheckpoint(0.5 + 0.35 * cos(t), 0.5 + 0.22 * sin(t)));
    }

    // AI cars
    _aiCars.clear();
    for (int i = 0; i < 3; i++) {
      double t = (i + 1) / 4 * 2 * pi - 0.2;
      _aiCars.add(DkAICar(
        x: 0.5 + 0.35 * cos(t), y: 0.5 + 0.22 * sin(t), angle: t + pi / 2,
        speed: 0.6 + _rnd.nextDouble() * 0.3,
        targetProgress: (i + 1) / 4,
      ));
    }
  }

  Future<void> _loadHS() async {
    final p = await SharedPreferences.getInstance();
    setState(() => _highScore = p.getInt('hi_score_drift_kings') ?? 0);
  }

  Future<void> _saveHS() async {
    if (_score > _highScore) {
      final p = await SharedPreferences.getInstance();
      await p.setInt('hi_score_drift_kings', _score);
      _highScore = _score;
    }
  }

  void _startGame() {
    _buildTrack();
    setState(() {
      _playing = true; _over = false; _raceOver = false;
      _score = 0; _lap = 0; _nitros = 3;
      _isGassing = false; _isBraking = false; _isNitroing = false; _nitroTimer = 0;
      _driftPoints = 0; _driftMult = 1.0; _damageFlash = 0;
      _lapTime = 0; _bestLapTime = 999;
      _px = _trackPath[0].dx; _py = _trackPath[0].dy;
      _pAngle = 0; _pSpeed = 0; _steerInput = 0; _driftAngle = 0;
      _nextCheckIdx = 0; _position = 1;
      _particles.clear();
    });
    HapticFeedback.mediumImpact();
  }

  void _useNitro() {
    if (_nitros <= 0 || _isNitroing) return;
    _nitros--;
    _isNitroing = true;
    _nitroTimer = 2.0;
    HapticFeedback.heavyImpact();
  }

  void _update() {
    if (!_playing || _over || _raceOver) return;
    const double dt = 1 / 60;
    _lapTime += dt;

    if (_damageFlash > 0) _damageFlash -= dt * 3;
    if (_nitroTimer > 0) { _nitroTimer -= dt; if (_nitroTimer <= 0) _isNitroing = false; }

    // Car physics
    double targetSpeed = _isGassing ? (_isNitroing ? 0.9 : 0.55) : _isBraking ? -0.2 : 0;
    _pSpeed += (targetSpeed - _pSpeed) * dt * 5;

    double steeringForce = _steerInput * 2.2 * min(1.0, _pSpeed.abs() * 3);
    _pAngle += steeringForce * dt;

    // Drift physics
    if (_steerInput.abs() > 0.5 && _pSpeed.abs() > 0.3) {
      _driftAngle = (_driftAngle + _steerInput * 0.6 * dt).clamp(-0.5, 0.5);
      _driftPoints += _pSpeed.abs() * 80 * dt;
      _driftMult = (1.0 + _driftPoints / 100).clamp(1, 4);
      _spawnTireSmoke();
    } else {
      _driftAngle *= 0.92;
      if (_driftPoints > 0) {
        int pts = (_driftPoints * _driftMult).toInt();
        _score += pts;
        _driftPoints = 0; _driftMult = 1.0;
      }
    }

    double moveAngle = _pAngle + _driftAngle;
    _px = (_px + cos(moveAngle) * _pSpeed * dt).clamp(0.05, 0.95);
    _py = (_py + sin(moveAngle) * _pSpeed * dt).clamp(0.05, 0.95);

    // Checkpoint detection
    DkCheckpoint ck = _checkpoints[_nextCheckIdx % _checkpoints.length];
    double dist = sqrt(pow(_px - ck.x, 2) + pow(_py - ck.y, 2));
    if (dist < 0.05) {
      _nextCheckIdx++;
      if (_nextCheckIdx >= _checkpoints.length) {
        _nextCheckIdx = 0;
        _lap++;
        if (_lapTime < _bestLapTime) _bestLapTime = _lapTime;
        _lapTime = 0;
        HapticFeedback.mediumImpact();
        if (_lap >= _totalLaps) _finishRace();
      }
    }

    // AI cars
    for (var ai in _aiCars) {
      ai.targetProgress = (ai.targetProgress + ai.speed * dt / (2 * pi * 0.35)) % 1.0;
      double t = ai.targetProgress * 2 * pi;
      double nx = 0.5 + 0.35 * cos(t) + (_rnd.nextDouble() - 0.5) * 0.02;
      double ny = 0.5 + 0.22 * sin(t) + (_rnd.nextDouble() - 0.5) * 0.02;
      ai.angle = atan2(ny - ai.y, nx - ai.x);
      ai.x = nx; ai.y = ny;
    }

    // Determine position
    _position = 1;
    for (var ai in _aiCars) {
      double aiDist = sqrt(pow(ai.x - ck.x, 2) + pow(ai.y - ck.y, 2));
      if (aiDist < dist) _position++;
    }

    // Particles
    for (int i = _particles.length - 1; i >= 0; i--) {
      var p = _particles[i];
      p.life -= dt; p.x += p.vx * dt; p.y += p.vy * dt;
      if (p.life <= 0) _particles.removeAt(i);
    }

    setState(() {});
  }

  void _spawnTireSmoke() {
    for (int i = 0; i < 2; i++) {
      _particles.add(DkParticle(
        x: _px + (_rnd.nextDouble() - 0.5) * 0.02,
        y: _py + (_rnd.nextDouble() - 0.5) * 0.02,
        vx: (_rnd.nextDouble() - 0.5) * 0.03,
        vy: (_rnd.nextDouble() - 0.5) * 0.03,
        life: 0.5 + _rnd.nextDouble() * 0.4,
        color: Colors.grey.withValues(alpha: 0.6),
        size: 4 + _rnd.nextDouble() * 6,
      ));
    }
    // Nitro trail
    if (_isNitroing) {
      _particles.add(DkParticle(
        x: _px, y: _py, vx: -cos(_pAngle) * 0.08, vy: -sin(_pAngle) * 0.08,
        life: 0.3, color: _kNeonO, size: 5,
      ));
    }
  }

  void _finishRace() {
    _raceOver = true;
    _position == 1 ? HapticFeedback.heavyImpact() : null;
    _raceResult = _position == 1 ? '🏆 1ST PLACE! YOU WIN!' : '${_position}${_position == 2 ? 'ND' : 'RD'} PLACE';
    _score += (_totalLaps * 500 ~/ _position);
    if (_bestLapTime < 999) _score += (1000 ~/ _bestLapTime.toInt()).clamp(0, 500);
    _saveHS();
    setState(() {});
  }

  @override
  void dispose() { _loop.dispose(); super.dispose(); }

  @override
  Widget build(BuildContext context) {
    return Scaffold(backgroundColor: _kBg, body: Stack(children: [
      if (_playing || _over) Positioned.fill(child: CustomPaint(painter: DkPainter(
        px: _px, py: _py, pAngle: _pAngle, driftAngle: _driftAngle, pSpeed: _pSpeed,
        isNitroing: _isNitroing, trackPath: List.from(_trackPath),
        checkpoints: List.from(_checkpoints), aiCars: List.from(_aiCars),
        particles: List.from(_particles), damageFlash: _damageFlash,
        nextCheckIdx: _nextCheckIdx, driftPoints: _driftPoints, driftMult: _driftMult,
      ))),

      // HUD
      if (_playing && !_over && !_raceOver) ...[
        Positioned(top: 44, left: 16, child: Column(crossAxisAlignment: CrossAxisAlignment.start, children: [
          Text('LAP ${min(_lap + 1, _totalLaps)}/$_totalLaps', style: TextStyle(color: _kNeonO, fontSize: 22, fontWeight: FontWeight.w900,
            shadows: [Shadow(color: _kNeonO, blurRadius: 10)])),
          Text('POSITION: ${_position == 1 ? '1ST 🥇' : _position == 2 ? '2ND 🥈' : '${_position}TH'}',
            style: const TextStyle(color: Colors.white, fontSize: 15, fontWeight: FontWeight.bold)),
          Text('SCORE: $_score', style: TextStyle(color: _kNeonY, fontSize: 14, fontWeight: FontWeight.bold)),
          if (_driftPoints > 5) Text('🔥 DRIFTING! x${_driftMult.toStringAsFixed(1)}',
            style: TextStyle(color: _kNeonO, fontSize: 14, fontWeight: FontWeight.bold,
              shadows: [Shadow(color: _kNeonO, blurRadius: 8)])),
        ])),
        Positioned(top: 44, right: 16, child: Column(crossAxisAlignment: CrossAxisAlignment.end, children: [
          Text('TIME: ${_lapTime.toStringAsFixed(1)}s', style: TextStyle(color: _kNeonC, fontSize: 14)),
          if (_bestLapTime < 999) Text('BEST: ${_bestLapTime.toStringAsFixed(1)}s', style: TextStyle(color: _kNeonG, fontSize: 13)),
          Text('NITROS: ${List.generate(_nitros, (_) => '⚡').join('')}', style: TextStyle(color: _kNeonY, fontSize: 14)),
        ])),
        // Controls
        Positioned(bottom: 16, left: 16, right: 16, child: SizedBox(height: 200, child: Row(
          mainAxisAlignment: MainAxisAlignment.spaceBetween, children: [
          // Steering joystick
          VirtualJoystick(size: 120, baseColor: Colors.white12, knobColor: _kNeonO,
            onDirectionChanged: (dir) => setState(() => _steerInput = dir.dx)),
          // Action buttons
          Column(mainAxisAlignment: MainAxisAlignment.center, children: [
            ActionButton(icon: Icons.local_gas_station_rounded, color: _kNeonG, label: 'GAS',
              onPressStart: () => setState(() => _isGassing = true),
              onPressEnd: () => setState(() => _isGassing = false),
              onPressed: () {}, size: 62),
            const SizedBox(height: 8),
            Row(children: [
              ActionButton(icon: Icons.pause_circle_filled_rounded, color: _kNeonR, label: 'BRAKE',
                onPressStart: () => setState(() => _isBraking = true),
                onPressEnd: () => setState(() => _isBraking = false),
                onPressed: () {}, size: 52),
              const SizedBox(width: 8),
              ActionButton(icon: Icons.electric_bolt_rounded, color: _kNeonY, label: 'NITRO',
                onPressed: _useNitro, size: 52),
            ]),
          ]),
        ]))),
      ],

      // Race finish
      if (_raceOver && _playing)
        Center(child: Container(
          margin: const EdgeInsets.all(24), padding: const EdgeInsets.all(28),
          decoration: BoxDecoration(color: Colors.black87, border: Border.all(color: _kNeonO, width: 2),
            borderRadius: BorderRadius.circular(24), boxShadow: [BoxShadow(color: _kNeonO.withValues(alpha: 0.5), blurRadius: 40)]),
          child: Column(mainAxisSize: MainAxisSize.min, children: [
            Text(_raceResult, textAlign: TextAlign.center, style: TextStyle(
              color: _kNeonO, fontSize: 28, fontWeight: FontWeight.w900, letterSpacing: 2,
              shadows: [Shadow(color: _kNeonO, blurRadius: 15)])),
            const SizedBox(height: 14),
            Text('SCORE: $_score', style: const TextStyle(color: Colors.white, fontSize: 22, fontWeight: FontWeight.bold)),
            if (_bestLapTime < 999) Text('BEST LAP: ${_bestLapTime.toStringAsFixed(1)}s', style: TextStyle(color: _kNeonG, fontSize: 15)),
            const SizedBox(height: 20),
            Row(mainAxisSize: MainAxisSize.min, children: [
              ElevatedButton(style: ElevatedButton.styleFrom(backgroundColor: _kNeonO),
                onPressed: _startGame, child: const Text('RACE AGAIN', style: TextStyle(color: Colors.black, fontWeight: FontWeight.bold))),
              const SizedBox(width: 12),
              OutlinedButton(style: OutlinedButton.styleFrom(side: const BorderSide(color: Colors.white30)),
                onPressed: () => setState(() { _raceOver = false; _playing = false; }),
                child: const Text('MENU', style: TextStyle(color: Colors.white54))),
            ]),
          ]),
        )),

      if (!_playing && !_over && !_raceOver) buildArenaStartPrompt(
        context: context, gameName: 'DRIFT KINGS', subtitle: 'NEON CIRCUIT RACING',
        story: 'Top-down neon drift racing. You are KINGPIN — the legendary Drift King. '
            'Race 3 AI opponents around the neon circuit. '
            'Drift corners for bonus points, use nitros for turbo speed, win all 3 laps!',
        controls: 'Left stick: Steer car • GAS button: Accelerate • BRAKE: Slow down\n'
            'NITRO: 2-second speed burst (3 charges) • High-speed corners = DRIFT BONUS',
        accentColor: _kNeonO, secondColor: _kNeonY,
        highScore: _highScore, onPlay: _startGame,
      ),
      if (_over) buildArenaGameOver(
        context: context, gameName: 'DRIFT KINGS', score: _score, highScore: _highScore,
        extra: 'LAP: $_lap/$_totalLaps', accentColor: _kNeonO,
        onRetry: _startGame,
        onMenu: () => setState(() { _over = false; _playing = false; }),
      ),
    ]));
  }
}

// ============================================================
// DRIFT KINGS PAINTER
// ============================================================
class DkPainter extends CustomPainter {
  final double px, py, pAngle, driftAngle, pSpeed, damageFlash, driftPoints, driftMult;
  final bool isNitroing;
  final int nextCheckIdx;
  final List<Offset> trackPath;
  final List<DkCheckpoint> checkpoints;
  final List<DkAICar> aiCars;
  final List<DkParticle> particles;

  DkPainter({required this.px, required this.py, required this.pAngle, required this.driftAngle,
    required this.pSpeed, required this.isNitroing, required this.trackPath, required this.checkpoints,
    required this.aiCars, required this.particles, required this.damageFlash,
    required this.nextCheckIdx, required this.driftPoints, required this.driftMult});

  @override
  void paint(Canvas canvas, Size size) {
    canvas.drawRect(Rect.fromLTWH(0, 0, size.width, size.height), Paint()..color = const Color(0xFF020215));

    // Background grid
    for (int i = 0; i < 20; i++) {
      canvas.drawLine(Offset(i * size.width / 20, 0), Offset(i * size.width / 20, size.height),
          Paint()..color = _kNeonB.withValues(alpha: 0.08)..strokeWidth = 0.5);
      canvas.drawLine(Offset(0, i * size.height / 20), Offset(size.width, i * size.height / 20),
          Paint()..color = _kNeonB.withValues(alpha: 0.08)..strokeWidth = 0.5);
    }

    // Track (outer + inner)
    if (trackPath.length > 2) {
      List<Offset> scaledOuter = trackPath.map((p) => Offset(p.dx * size.width, p.dy * size.height)).toList();
      List<Offset> scaledInner = trackPath.map((p) {
        Offset center = Offset(0.5 * size.width, 0.5 * size.height);
        Offset dir = (Offset(p.dx * size.width, p.dy * size.height) - center);
        double len = dir.distance;
        return center + dir / len * (len - 40);
      }).toList();

      // Track fill
      Path outerPath = Path()..addPolygon(scaledOuter, true);
      Path innerPath = Path()..addPolygon(scaledInner, true);
      Path trackFill = Path.combine(PathOperation.difference, outerPath, innerPath);
      canvas.drawPath(trackFill, Paint()..color = const Color(0xFF121230));
      canvas.drawPath(outerPath, Paint()..color = _kNeonO.withValues(alpha: 0.4)
        ..style = PaintingStyle.stroke..strokeWidth = 2
        ..maskFilter = const MaskFilter.blur(BlurStyle.normal, 3));
      canvas.drawPath(innerPath, Paint()..color = _kNeonO.withValues(alpha: 0.3)
        ..style = PaintingStyle.stroke..strokeWidth = 1.5);

      // Dashed center line
      Paint dashPaint = Paint()..color = _kNeonY.withValues(alpha: 0.2)..strokeWidth = 1;
      for (int i = 0; i < scaledOuter.length; i++) {
        if (i % 3 == 0) {
          Offset mid = (scaledOuter[i] + scaledInner[i]) / 2;
          Offset nextMid = (scaledOuter[(i + 1) % scaledOuter.length] + scaledInner[(i + 1) % scaledInner.length]) / 2;
          canvas.drawLine(mid, nextMid, dashPaint);
        }
      }
    }

    // Checkpoints
    for (int i = 0; i < checkpoints.length; i++) {
      var c = checkpoints[i];
      bool isNext = i == nextCheckIdx % checkpoints.length;
      canvas.drawCircle(Offset(c.x * size.width, c.y * size.height), isNext ? 14 : 8,
          Paint()..color = (isNext ? _kNeonG : Colors.white24)..style = PaintingStyle.stroke..strokeWidth = 2
            ..maskFilter = isNext ? const MaskFilter.blur(BlurStyle.normal, 6) : null);
    }

    // AI cars
    for (var ai in aiCars) {
      canvas.save();
      canvas.translate(ai.x * size.width, ai.y * size.height);
      canvas.rotate(ai.angle);
      canvas.drawRRect(RRect.fromRectAndRadius(Rect.fromCenter(center: Offset(0, 0), width: 14, height: 22), const Radius.circular(3)),
          Paint()..color = const Color(0xFF880088));
      canvas.drawRRect(RRect.fromRectAndRadius(Rect.fromCenter(center: Offset(0, 0), width: 14, height: 22), const Radius.circular(3)),
          Paint()..color = _kNeonM.withValues(alpha: 0.5)..style = PaintingStyle.stroke..strokeWidth = 1.5);
      canvas.restore();
    }

    // Tire smoke particles
    for (var p in particles) {
      canvas.drawCircle(Offset(p.x * size.width, p.y * size.height), p.size,
          Paint()..color = p.color.withValues(alpha: p.life.clamp(0, 1))
            ..maskFilter = MaskFilter.blur(BlurStyle.normal, p.size * 0.5));
    }

    // Player car
    canvas.save();
    canvas.translate(px * size.width, py * size.height);
    canvas.rotate(pAngle + driftAngle);

    // Car body glow
    Color carColor = isNitroing ? _kNeonO : _kNeonY;
    canvas.drawRRect(RRect.fromRectAndRadius(Rect.fromCenter(center: Offset(0, 0), width: 20, height: 32), const Radius.circular(4)),
        Paint()..color = carColor.withValues(alpha: 0.35)..maskFilter = const MaskFilter.blur(BlurStyle.normal, 10));

    // Car body
    canvas.drawRRect(RRect.fromRectAndRadius(Rect.fromCenter(center: Offset(0, 0), width: 20, height: 32), const Radius.circular(4)),
        Paint()..color = carColor.withValues(alpha: 0.85));
    canvas.drawRRect(RRect.fromRectAndRadius(Rect.fromCenter(center: Offset(0, 0), width: 20, height: 32), const Radius.circular(4)),
        Paint()..color = carColor..style = PaintingStyle.stroke..strokeWidth = 2
          ..maskFilter = const MaskFilter.blur(BlurStyle.normal, 4));

    // Windshield
    canvas.drawRRect(RRect.fromRectAndRadius(Rect.fromCenter(center: Offset(0, -6), width: 14, height: 8), const Radius.circular(2)),
        Paint()..color = _kNeonC.withValues(alpha: 0.5)..maskFilter = const MaskFilter.blur(BlurStyle.normal, 2));

    // Wheels
    for (int i = 0; i < 4; i++) {
      double wx = i < 2 ? -11 : 11;
      double wy = i % 2 == 0 ? -10 : 10;
      canvas.drawRect(Rect.fromCenter(center: Offset(wx, wy), width: 5, height: 8), Paint()..color = Colors.black);
      canvas.drawRect(Rect.fromCenter(center: Offset(wx, wy), width: 5, height: 8),
          Paint()..color = Colors.grey..style = PaintingStyle.stroke..strokeWidth = 1);
    }

    // Nitro flames
    if (isNitroing) {
      Path flame = Path()
        ..moveTo(-4, 16) ..lineTo(0, 40) ..lineTo(4, 16);
      canvas.drawPath(flame, Paint()..color = _kNeonO.withValues(alpha: 0.8)
        ..maskFilter = const MaskFilter.blur(BlurStyle.normal, 8));
      canvas.drawPath(flame, Paint()..color = Colors.white..maskFilter = const MaskFilter.blur(BlurStyle.normal, 2));
    }

    canvas.restore();

    // Drift point text
    if (driftPoints > 5) {
      final tp = TextPainter(
        text: TextSpan(text: '+${driftPoints.toInt()} x${driftMult.toStringAsFixed(1)}',
          style: TextStyle(color: _kNeonO, fontSize: 18, fontWeight: FontWeight.bold,
            shadows: [Shadow(color: _kNeonO, blurRadius: 12)])),
        textDirection: TextDirection.ltr,
      )..layout();
      tp.paint(canvas, Offset(px * size.width - tp.width / 2, py * size.height - 50));
    }

    if (damageFlash > 0) {
      canvas.drawRect(Rect.fromLTWH(0, 0, size.width, size.height),
          Paint()..color = _kNeonR.withValues(alpha: damageFlash * 0.35));
    }
  }

  @override
  bool shouldRepaint(covariant CustomPainter old) => true;
}

